#[derive(Clone, Debug, Parser)]
#[command(about = "A fast native genome viewer written in Rust")]
struct LaunchOptions {
    /// Indexed BAM or CRAM file to open. If omitted, the synthetic GPU demo is shown.
    #[arg(long)]
    bam: Option<PathBuf>,
    /// Reference FASTA used for CRAM decoding and future base-level comparison.
    #[arg(long)]
    reference: Option<PathBuf>,
    /// Explicit BAI, CSI, or CRAI URL for a remote BAM/CRAM. Conventional adjacent URLs are tried otherwise.
    #[arg(long)]
    remote_index_url: Option<String>,
    /// Explicit FAI URL for a remote reference FASTA. The conventional `.fai` URL is used otherwise.
    #[arg(long)]
    remote_reference_index_url: Option<String>,
    /// Initial one-based locus, for example chr1:900001-920000.
    #[arg(long)]
    locus: Option<String>,
    /// Display name for the reference assembly loaded from the alignment header.
    #[arg(long, default_value = "BAM header")]
    genome_name: String,
    /// Portable JSON genome bundle describing FASTA, aliases, cytobands, and default annotations.
    #[arg(long, conflicts_with_all = ["session", "import_igv"])]
    genome_config: Option<PathBuf>,
    /// UCSC cytoband TSV used to draw chromosome ideograms.
    #[arg(long)]
    cytobands: Option<PathBuf>,
    /// Explicit contig alias in ALIAS=CANONICAL form. May be repeated.
    #[arg(long = "contig-alias", value_name = "ALIAS=CANONICAL")]
    contig_aliases: Vec<String>,
    /// Maximum number of individual alignments retained from a deep query.
    #[arg(long, default_value_t = 50_000)]
    max_alignments: usize,
    /// BED or BED12 feature track. May be repeated.
    #[arg(long)]
    bed: Vec<PathBuf>,
    /// GFF3 gene or feature track. May be repeated.
    #[arg(long)]
    gff: Vec<PathBuf>,
    /// GTF gene model track. May be repeated.
    #[arg(long)]
    gtf: Vec<PathBuf>,
    /// UCSC genePred transcript model. May be repeated.
    #[arg(long)]
    gene_pred: Vec<PathBuf>,
    /// UCSC refFlat transcript model. May be repeated.
    #[arg(long)]
    ref_flat: Vec<PathBuf>,
    /// ENCODE narrowPeak BED6+4 feature track. May be repeated.
    #[arg(long)]
    narrow_peak: Vec<PathBuf>,
    /// ENCODE broadPeak BED6+3 feature track. May be repeated.
    #[arg(long)]
    broad_peak: Vec<PathBuf>,
    /// UCSC PSL target-alignment track. May be repeated.
    #[arg(long)]
    psl: Vec<PathBuf>,
    /// IGV/PLINK-compatible GWAS summary track. May be repeated.
    #[arg(long)]
    gwas: Vec<PathBuf>,
    /// Indexed VCF or BCF variant track. May be repeated.
    #[arg(long)]
    vcf: Vec<PathBuf>,
    /// `BigWig` quantitative track. May be repeated.
    #[arg(long)]
    bigwig: Vec<PathBuf>,
    /// IGV tiled data format (TDF) quantitative track. May be repeated.
    #[arg(long)]
    tdf: Vec<PathBuf>,
    /// bedGraph quantitative track. May be repeated.
    #[arg(long)]
    bedgraph: Vec<PathBuf>,
    /// fixedStep or variableStep WIG quantitative track. May be repeated.
    #[arg(long)]
    wig: Vec<PathBuf>,
    /// BEDPE interaction track. May be repeated.
    #[arg(long)]
    bedpe: Vec<PathBuf>,
    /// UCSC 18-column interact track. May be repeated.
    #[arg(long)]
    interact: Vec<PathBuf>,
    /// SEG/CBS multi-sample segmented copy-number track. May be repeated.
    #[arg(long)]
    seg: Vec<PathBuf>,
    /// Mutation Annotation Format (cancer MAF) track. May be repeated.
    #[arg(long)]
    maf: Vec<PathBuf>,
    /// `BigBed` feature track. May be repeated.
    #[arg(long)]
    bigbed: Vec<PathBuf>,
    /// UCSC bigGenePred (`BigBed` BED12+8) transcript track. May be repeated.
    #[arg(long)]
    big_gene_pred: Vec<PathBuf>,
    /// ENCODE bigNarrowPeak (`BigBed` BED6+4) peak track. May be repeated.
    #[arg(long)]
    big_narrow_peak: Vec<PathBuf>,
    /// Open a native RGV JSON session.
    #[arg(long, conflicts_with = "import_igv")]
    session: Option<PathBuf>,
    /// Import a subset of an IGV XML session.
    #[arg(long)]
    import_igv: Option<PathBuf>,
    /// Override the platform settings-file location.
    #[arg(long)]
    settings_path: Option<PathBuf>,
    /// Run a versioned deterministic automation batch.
    #[arg(long)]
    batch: Option<PathBuf>,
    /// Write structured automation results here (defaults beside the batch).
    #[arg(long, requires = "batch")]
    automation_report: Option<PathBuf>,
    /// Enable authenticated local control on 127.0.0.1 at this port. Port 0 selects a free port.
    #[arg(long, requires = "control_secret_file", conflicts_with = "batch")]
    control_port: Option<u16>,
    /// Read the local-control bearer secret from this protected file.
    #[arg(long, requires = "control_port", conflicts_with = "batch")]
    control_secret_file: Option<PathBuf>,
    /// Restrict local-control input and output paths to this directory.
    #[arg(long, requires = "control_port")]
    control_root: Option<PathBuf>,
    #[arg(skip)]
    loaded_session: Option<SessionDocument>,
    #[arg(skip)]
    loaded_genome: Option<GenomeConfiguration>,
    #[arg(skip)]
    loaded_settings: DesktopSettings,
    #[arg(skip)]
    loaded_igv_report: Option<IgvImportReport>,
    #[arg(skip)]
    recovered_unclean_exit: bool,
    #[arg(skip)]
    recovery_candidates: Vec<PathBuf>,
    #[arg(skip)]
    loaded_batch: Option<AutomationBatch>,
    #[arg(skip)]
    control_secret: Option<String>,
}

impl LaunchOptions {
    fn load_session(&mut self) -> Result<()> {
        let settings_path = self
            .settings_path
            .clone()
            .unwrap_or_else(default_settings_path);
        self.settings_path = Some(settings_path.clone());
        self.loaded_batch = self
            .batch
            .as_ref()
            .map(AutomationBatch::read)
            .transpose()
            .context("failed to read automation batch")?;
        self.load_control_configuration()?;
        self.loaded_settings = if settings_path.exists() {
            match DesktopSettings::read(&settings_path) {
                Ok(settings) => settings,
                Err(error) => {
                    tracing::warn!(path = %settings_path.display(), %error, "ignoring invalid settings file");
                    DesktopSettings::default()
                }
            }
        } else {
            DesktopSettings::default()
        };
        self.loaded_genome = if let Some(path) = &self.genome_config {
            let configuration = GenomeConfiguration::read(path).with_context(|| {
                format!("failed to read genome configuration {}", path.display())
            })?;
            self.reference = Some(source_path(&configuration.reference));
            self.genome_name.clone_from(&configuration.name);
            self.cytobands = match &configuration.cytobands {
                Some(TrackSource::Local { path }) => Some(PathBuf::from(path)),
                Some(TrackSource::Remote { .. }) => {
                    anyhow::bail!("remote cytoband files are not yet supported")
                }
                None => None,
            };
            Some(configuration)
        } else {
            None
        };
        let document = if let Some(path) = &self.session {
            Some(
                SessionDocument::read(path)
                    .with_context(|| format!("failed to read RGV session {}", path.display()))?,
            )
        } else if let Some(path) = &self.import_igv {
            let xml = std::fs::read_to_string(path)
                .with_context(|| format!("failed to read IGV session {}", path.display()))?;
            let imported = SessionDocument::import_igv_with_report(&xml)
                .with_context(|| format!("failed to import IGV session {}", path.display()))?;
            let mut document = imported.document;
            let parent = path
                .parent()
                .filter(|parent| !parent.as_os_str().is_empty())
                .unwrap_or_else(|| Path::new("."));
            document.resolve_project_paths(std::path::absolute(parent)?);
            self.loaded_igv_report = Some(imported.report);
            Some(document)
        } else {
            None
        };
        if let Some(document) = &document {
            self.bam = primary_alignment_track(document).map(|track| source_path(&track.source));
            self.reference = document.reference.as_ref().map(source_path);
            if let Some(name) = &document.genome_name {
                self.genome_name.clone_from(name);
            }
            self.cytobands = match &document.cytobands {
                Some(TrackSource::Local { path }) => Some(PathBuf::from(path)),
                Some(TrackSource::Remote { .. }) => {
                    anyhow::bail!("remote session cytoband files are not yet supported")
                }
                None => None,
            };
            self.locus = Some(format!(
                "{}:{}-{}",
                document.locus.contig,
                document.locus.start + 1,
                document.locus.end
            ));
            self.max_alignments = primary_alignment_track(document)
                .map_or(document.maximum_alignments, |track| {
                    track.maximum_alignments
                })
                .min(document.maximum_alignments);
        }
        self.loaded_session = document;
        Ok(())
    }

    fn load_control_configuration(&mut self) -> Result<()> {
        if self.control_port.is_none() {
            return Ok(());
        }
        let secret_path = self
            .control_secret_file
            .as_deref()
            .context("--control-port requires --control-secret-file")?;
        self.control_secret = Some(
            read_control_secret(secret_path)
                .map_err(anyhow::Error::msg)
                .context("invalid local-control secret")?,
        );
        let root = self
            .control_root
            .clone()
            .unwrap_or(std::env::current_dir().context("could not resolve the current directory")?);
        self.control_root = Some(
            root.canonicalize()
                .with_context(|| format!("could not resolve control root {}", root.display()))?,
        );
        Ok(())
    }
}

fn default_settings_path() -> PathBuf {
    if let Some(directory) = std::env::var_os("RGV_CONFIG_DIR") {
        return PathBuf::from(directory).join("settings.json");
    }
    #[cfg(target_os = "windows")]
    if let Some(directory) = std::env::var_os("APPDATA") {
        return PathBuf::from(directory).join("RGV").join("settings.json");
    }
    #[cfg(target_os = "macos")]
    if let Some(directory) = std::env::var_os("HOME") {
        return PathBuf::from(directory)
            .join("Library")
            .join("Application Support")
            .join("RGV")
            .join("settings.json");
    }
    #[cfg(not(any(target_os = "windows", target_os = "macos")))]
    {
        if let Some(directory) = std::env::var_os("XDG_CONFIG_HOME") {
            return PathBuf::from(directory).join("rgv").join("settings.json");
        }
        if let Some(directory) = std::env::var_os("HOME") {
            return PathBuf::from(directory)
                .join(".config")
                .join("rgv")
                .join("settings.json");
        }
    }
    PathBuf::from("rgv-settings.json")
}

const MAX_RECOVERY_CANDIDATES: usize = 100;

fn autosave_directory(settings_path: &Path) -> PathBuf {
    settings_path.with_file_name("autosaves")
}

fn stable_path_hash(path: Option<&Path>) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    let value = path.map_or_else(|| "untitled".into(), |path| path.to_string_lossy());
    for byte in value.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn autosave_group_prefix(project_path: Option<&Path>) -> String {
    let label = project_path
        .and_then(Path::file_stem)
        .and_then(|value| value.to_str())
        .unwrap_or("untitled");
    let mut safe = label
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_') {
                character
            } else {
                '_'
            }
        })
        .take(32)
        .collect::<String>();
    if safe.is_empty() {
        safe.push_str("project");
    }
    format!("{safe}-{:016x}", stable_path_hash(project_path))
}

fn autosave_snapshot_path(
    settings_path: &Path,
    project_path: Option<&Path>,
    now: SystemTime,
) -> (PathBuf, String) {
    let prefix = autosave_group_prefix(project_path);
    let milliseconds = now
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis();
    let name = format!("{prefix}-{milliseconds:020}.autosave.json");
    (autosave_directory(settings_path).join(name), prefix)
}

fn prune_autosaves(directory: &Path, prefix: &str, retention: usize) -> std::io::Result<()> {
    let file_prefix = format!("{prefix}-");
    let mut matching = std::fs::read_dir(directory)?
        .filter_map(std::result::Result::ok)
        .map(|entry| entry.path())
        .filter(|path| {
            path.file_name()
                .and_then(|value| value.to_str())
                .is_some_and(|name| {
                    name.starts_with(&file_prefix) && name.ends_with(".autosave.json")
                })
        })
        .collect::<Vec<_>>();
    matching.sort_unstable();
    let remove_count = matching.len().saturating_sub(retention);
    for path in matching.into_iter().take(remove_count) {
        std::fs::remove_file(path)?;
    }
    Ok(())
}

fn discover_recovery_candidates(settings_path: &Path) -> Vec<PathBuf> {
    let Ok(entries) = std::fs::read_dir(autosave_directory(settings_path)) else {
        return Vec::new();
    };
    let mut candidates = entries
        .filter_map(std::result::Result::ok)
        .map(|entry| entry.path())
        .filter(|path| {
            path.file_name()
                .and_then(|value| value.to_str())
                .is_some_and(|name| name.ends_with(".autosave.json"))
        })
        .collect::<Vec<_>>();
    candidates.sort_unstable_by(|left, right| right.cmp(left));
    candidates.truncate(MAX_RECOVERY_CANDIDATES);
    candidates
}

#[allow(clippy::too_many_lines)]
fn build_track_specs(options: &LaunchOptions) -> (Vec<TrackSpec>, TrackCollection) {
    if let Some(session) = &options.loaded_session {
        return session_track_specs(session);
    }
    let mut specifications = Vec::new();
    let mut tracks = TrackCollection::default();
    let mut next_id = 1_u64;
    for (paths, specification_kind, track_kind, format) in [
        (&options.bed, TrackSpecKind::Bed, TrackKind::Feature, None),
        (
            &options.gff,
            TrackSpecKind::Gff3,
            TrackKind::GeneModel,
            None,
        ),
        (&options.gtf, TrackSpecKind::Gtf, TrackKind::GeneModel, None),
        (
            &options.gene_pred,
            TrackSpecKind::GenePred,
            TrackKind::GeneModel,
            None,
        ),
        (
            &options.ref_flat,
            TrackSpecKind::RefFlat,
            TrackKind::GeneModel,
            None,
        ),
        (
            &options.narrow_peak,
            TrackSpecKind::NarrowPeak,
            TrackKind::Feature,
            None,
        ),
        (
            &options.broad_peak,
            TrackSpecKind::BroadPeak,
            TrackKind::Feature,
            None,
        ),
        (&options.psl, TrackSpecKind::Psl, TrackKind::Feature, None),
        (&options.gwas, TrackSpecKind::Gwas, TrackKind::Gwas, None),
        (
            &options.vcf,
            TrackSpecKind::VcfOrBcf,
            TrackKind::Variant,
            None,
        ),
        (
            &options.bigwig,
            TrackSpecKind::BigWig,
            TrackKind::Quantitative,
            None,
        ),
        (
            &options.tdf,
            TrackSpecKind::Tdf,
            TrackKind::Quantitative,
            None,
        ),
        (
            &options.bedgraph,
            TrackSpecKind::BedGraph,
            TrackKind::Quantitative,
            None,
        ),
        (
            &options.wig,
            TrackSpecKind::Wig,
            TrackKind::Quantitative,
            None,
        ),
        (
            &options.bedpe,
            TrackSpecKind::BedPe,
            TrackKind::Interaction,
            None,
        ),
        (
            &options.interact,
            TrackSpecKind::Interact,
            TrackKind::Interaction,
            None,
        ),
        (
            &options.seg,
            TrackSpecKind::Seg,
            TrackKind::CopyNumber,
            None,
        ),
        (
            &options.maf,
            TrackSpecKind::MutationMaf,
            TrackKind::Mutation,
            None,
        ),
        (
            &options.bigbed,
            TrackSpecKind::BigBed,
            TrackKind::Feature,
            None,
        ),
        (
            &options.big_gene_pred,
            TrackSpecKind::BigGenePred,
            TrackKind::GeneModel,
            Some(TrackFormat::BigGenePred),
        ),
        (
            &options.big_narrow_peak,
            TrackSpecKind::BigNarrowPeak,
            TrackKind::Feature,
            Some(TrackFormat::BigNarrowPeak),
        ),
    ] {
        for path in paths {
            let id = TrackId::new(next_id);
            next_id = next_id.saturating_add(1);
            let name = path.file_name().map_or_else(
                || path.display().to_string(),
                |name| name.to_string_lossy().into_owned(),
            );
            specifications.push(TrackSpec {
                id,
                name: name.clone(),
                path: path.clone(),
                kind: specification_kind,
            });
            let mut config = TrackConfig::new(id, name, track_kind, track_source(path));
            config.format = format;
            tracks.push(config);
        }
    }
    if let Some(genome) = &options.loaded_genome {
        for annotation in &genome.default_annotations {
            let Some(kind) = track_spec_kind(annotation.kind, &annotation.source, None) else {
                continue;
            };
            let id = TrackId::new(next_id);
            next_id = next_id.saturating_add(1);
            specifications.push(TrackSpec {
                id,
                name: annotation.name.clone(),
                path: source_path(&annotation.source),
                kind,
            });
            tracks.push(TrackConfig::new(
                id,
                annotation.name.clone(),
                annotation.kind,
                annotation.source.clone(),
            ));
        }
    }
    (specifications, tracks)
}

fn session_track_specs(session: &SessionDocument) -> (Vec<TrackSpec>, TrackCollection) {
    let mut specifications = Vec::new();
    let mut tracks = TrackCollection::default();
    for track in &session.tracks {
        let Some(kind) = track_spec_kind(track.kind, &track.source, track.format) else {
            continue;
        };
        specifications.push(TrackSpec {
            id: track.id,
            name: track.name.clone(),
            path: source_path(&track.source),
            kind,
        });
        tracks.push(track.clone());
    }
    (specifications, tracks)
}

fn source_path(source: &TrackSource) -> PathBuf {
    match source {
        TrackSource::Local { path } => PathBuf::from(path),
        TrackSource::Remote { url } => PathBuf::from(url),
    }
}

fn tdf_channel_display_name(base_name: &str, embedded_name: &str, index: usize) -> String {
    let embedded_name = embedded_name.trim();
    if embedded_name.is_empty() {
        format!("{base_name} · channel {}", index + 1)
    } else {
        embedded_name.to_owned()
    }
}

struct TdfChannelExpansion {
    selected_name: String,
    specifications: Vec<TrackSpec>,
    children: Vec<TrackConfig>,
}

fn build_tdf_channel_expansion(
    parent: &TrackConfig,
    path: &Path,
    track_names: &[String],
    selected_index: usize,
    mut next_id: u64,
) -> Result<TdfChannelExpansion> {
    if track_names.is_empty() || selected_index >= track_names.len() {
        anyhow::bail!("TDF source returned an invalid embedded-channel catalogue");
    }
    let mut specifications = Vec::with_capacity(track_names.len().saturating_sub(1));
    let mut children = Vec::with_capacity(track_names.len().saturating_sub(1));
    for (index, embedded_name) in track_names.iter().enumerate() {
        if index == selected_index {
            continue;
        }
        let id = TrackId::new(next_id);
        next_id = next_id
            .checked_add(1)
            .ok_or_else(|| anyhow::anyhow!("TDF channel track ID space is exhausted"))?;
        let name = tdf_channel_display_name(&parent.name, embedded_name, index);
        specifications.push(TrackSpec {
            id,
            name: name.clone(),
            path: path.to_path_buf(),
            kind: TrackSpecKind::TdfChannel { index },
        });
        let mut child = parent.clone();
        child.id = id;
        child.name = name;
        child.format = Some(TrackFormat::TdfChannel { index });
        children.push(child);
    }
    Ok(TdfChannelExpansion {
        selected_name: tdf_channel_display_name(
            &parent.name,
            &track_names[selected_index],
            selected_index,
        ),
        specifications,
        children,
    })
}

fn inferred_automation_track_kind(source: &TrackSource, explicit: Option<TrackKind>) -> TrackKind {
    if let Some(kind) = explicit {
        return kind;
    }
    let label = source.redacted_label();
    let extension = Path::new(&label)
        .extension()
        .map(|extension| extension.to_string_lossy().to_ascii_lowercase())
        .unwrap_or_default();
    let inner_extension = Path::new(&label)
        .file_stem()
        .and_then(|value| Path::new(value).extension())
        .map(|extension| extension.to_string_lossy().to_ascii_lowercase());
    let effective_extension = if extension == "gz" {
        inner_extension.as_deref().unwrap_or(extension.as_str())
    } else {
        extension.as_str()
    };
    match effective_extension {
        "bam" | "cram" => TrackKind::Alignment,
        "fa" | "fasta" | "fna" => TrackKind::Reference,
        "linear" | "logistic" | "assoc" | "qassoc" | "gwas" => TrackKind::Gwas,
        "tdf" => TrackKind::Quantitative,
        _ => TrackKind::Feature,
    }
}

fn opened_project_status(path: &Path, unresolved: &[UnresolvedSessionSource]) -> String {
    if unresolved.is_empty() {
        return format!("Opened project {}", path.display());
    }
    let sources = unresolved
        .iter()
        .map(|issue| format!("{}: {}", issue.label, issue.path.display()))
        .collect::<Vec<_>>()
        .join(" · ");
    format!(
        "Opened project {} with {} unresolved local source(s) · {sources}",
        path.display(),
        unresolved.len()
    )
}

fn primary_alignment_track(session: &SessionDocument) -> Option<&SessionAlignmentTrack> {
    session.alignment_tracks.first()
}

fn upsert_primary_alignment_config<'a>(
    alignment_tracks: &'a mut Vec<SessionAlignmentTrack>,
    auxiliary_tracks: &[TrackConfig],
    source: TrackSource,
    name: &str,
) -> &'a mut SessionAlignmentTrack {
    if alignment_tracks.is_empty() {
        let next_id = alignment_tracks
            .iter()
            .map(|track| track.id.get())
            .chain(auxiliary_tracks.iter().map(|track| track.id.get()))
            .max()
            .unwrap_or_default()
            .saturating_add(1);
        alignment_tracks.push(SessionAlignmentTrack::new(
            TrackId::new(next_id),
            name.to_owned(),
            source.clone(),
        ));
    }
    let primary = &mut alignment_tracks[0];
    name.clone_into(&mut primary.name);
    primary.source = source;
    primary
}

fn source_display_name(source: Option<&TrackSource>, fallback: &str) -> String {
    source.map_or_else(
        || fallback.to_owned(),
        |source| {
            let label = source.redacted_label();
            Path::new(&label)
                .file_name()
                .map_or(label.clone(), |name| name.to_string_lossy().into_owned())
        },
    )
}

fn load_assembly(
    name: &str,
    dictionary: ReferenceDictionary,
    cytoband_path: Option<&Path>,
) -> GenomeAssembly {
    let mut assembly = GenomeAssembly::from_dictionary(name, dictionary);
    let Some(path) = cytoband_path else {
        return assembly;
    };
    match std::fs::read_to_string(path)
        .with_context(|| format!("failed to read cytobands from {}", path.display()))
        .and_then(|text| parse_ucsc_cytobands(&text, &assembly.dictionary).map_err(Into::into))
    {
        Ok(cytobands) => assembly.cytobands = cytobands,
        Err(error) => tracing::warn!(path = %path.display(), %error, "using ideogram fallback"),
    }
    assembly
}

fn alignment_open_options(
    reference_path: Option<PathBuf>,
    remote_index_url: Option<String>,
    remote_reference_index_url: Option<String>,
) -> AlignmentOpenOptions {
    let mut options = AlignmentOpenOptions {
        reference_path,
        remote_index_url,
        remote_reference_index_url,
        ..AlignmentOpenOptions::default()
    };
    options.remote_range = remote_range_config();
    options
}

fn reference_open_options(remote_index_url: Option<String>) -> FastaOpenOptions {
    FastaOpenOptions {
        remote_index_url,
        remote_range: remote_range_config(),
    }
}

fn remote_range_config() -> HttpRangeConfig {
    let mut config = HttpRangeConfig {
        minimum_coalesced_chunks: NonZeroUsize::new(8).unwrap(),
        maximum_coalesced_chunks: NonZeroUsize::new(8).unwrap(),
        ..HttpRangeConfig::default()
    };
    if let Ok(token) = std::env::var("RGV_REMOTE_BEARER_TOKEN")
        && !token.is_empty()
    {
        config.authentication = RemoteAuthentication::Bearer(token);
    }
    config
}

fn track_spec_kind(
    kind: TrackKind,
    source: &TrackSource,
    format: Option<TrackFormat>,
) -> Option<TrackSpecKind> {
    if let Some(format) = format {
        return Some(match format {
            TrackFormat::BigGenePred => TrackSpecKind::BigGenePred,
            TrackFormat::BigNarrowPeak => TrackSpecKind::BigNarrowPeak,
            TrackFormat::TdfChannel { index } => TrackSpecKind::TdfChannel { index },
        });
    }
    let path = source_path(source);
    let (extension, inner_extension) = source_extensions(&path);
    let effective_extension = if extension == "gz" {
        inner_extension.as_deref().unwrap_or(extension.as_str())
    } else {
        extension.as_str()
    };
    match kind {
        TrackKind::Feature => Some(match effective_extension {
            "bignarrowpeak" => TrackSpecKind::BigNarrowPeak,
            "bb" | "bigbed" => TrackSpecKind::BigBed,
            "narrowpeak" => TrackSpecKind::NarrowPeak,
            "broadpeak" => TrackSpecKind::BroadPeak,
            "psl" => TrackSpecKind::Psl,
            _ => TrackSpecKind::Bed,
        }),
        TrackKind::GeneModel => Some(match effective_extension {
            "biggenepred" | "bb" | "bigbed" => TrackSpecKind::BigGenePred,
            "gtf" => TrackSpecKind::Gtf,
            "genepred" | "gp" => TrackSpecKind::GenePred,
            "refflat" => TrackSpecKind::RefFlat,
            _ => TrackSpecKind::Gff3,
        }),
        TrackKind::Variant => Some(TrackSpecKind::VcfOrBcf),
        TrackKind::Mutation => Some(TrackSpecKind::MutationMaf),
        TrackKind::Gwas => Some(TrackSpecKind::Gwas),
        TrackKind::Quantitative => Some(match effective_extension {
            "bedgraph" | "bdg" => TrackSpecKind::BedGraph,
            "wig" | "wiggle" => TrackSpecKind::Wig,
            "tdf" => TrackSpecKind::Tdf,
            _ => TrackSpecKind::BigWig,
        }),
        TrackKind::CopyNumber => Some(TrackSpecKind::Seg),
        TrackKind::Interaction => Some(if effective_extension == "interact" {
            TrackSpecKind::Interact
        } else {
            TrackSpecKind::BedPe
        }),
        TrackKind::Alignment | TrackKind::Reference => None,
    }
}

fn source_extensions(path: &Path) -> (String, Option<String>) {
    let value = path.to_string_lossy();
    let path_without_url_suffix = value.split(['?', '#']).next().unwrap_or(&value);
    let path = Path::new(path_without_url_suffix);
    let extension = path
        .extension()
        .map(|value| value.to_string_lossy().to_ascii_lowercase())
        .unwrap_or_default();
    let inner_extension = path
        .file_stem()
        .and_then(|value| Path::new(value).extension())
        .map(|value| value.to_string_lossy().to_ascii_lowercase());
    (extension, inner_extension)
}

fn inferred_desktop_track_kind(path: &Path) -> Result<(TrackSpecKind, TrackKind)> {
    let (extension, inner_extension) = source_extensions(path);
    let compressed = extension == "gz";
    if extension == "txt" && inner_extension.as_deref() == Some("maf") {
        return Ok((TrackSpecKind::MutationMaf, TrackKind::Mutation));
    }
    let effective_extension = if compressed {
        inner_extension.as_deref().unwrap_or(extension.as_str())
    } else {
        extension.as_str()
    };
    let inferred = match effective_extension {
        "bed" => (TrackSpecKind::Bed, TrackKind::Feature),
        "gff" | "gff3" => (TrackSpecKind::Gff3, TrackKind::GeneModel),
        "gtf" => (TrackSpecKind::Gtf, TrackKind::GeneModel),
        "genepred" | "gp" => (TrackSpecKind::GenePred, TrackKind::GeneModel),
        "refflat" => (TrackSpecKind::RefFlat, TrackKind::GeneModel),
        "narrowpeak" => (TrackSpecKind::NarrowPeak, TrackKind::Feature),
        "broadpeak" => (TrackSpecKind::BroadPeak, TrackKind::Feature),
        "psl" => (TrackSpecKind::Psl, TrackKind::Feature),
        "linear" | "logistic" | "assoc" | "qassoc" | "gwas" => {
            (TrackSpecKind::Gwas, TrackKind::Gwas)
        }
        "vcf" => (TrackSpecKind::VcfOrBcf, TrackKind::Variant),
        "maf" => (TrackSpecKind::MutationMaf, TrackKind::Mutation),
        "bcf" if !compressed => (TrackSpecKind::VcfOrBcf, TrackKind::Variant),
        "bw" | "bigwig" if !compressed => (TrackSpecKind::BigWig, TrackKind::Quantitative),
        "tdf" if !compressed => (TrackSpecKind::Tdf, TrackKind::Quantitative),
        "bedgraph" | "bdg" if !compressed => (TrackSpecKind::BedGraph, TrackKind::Quantitative),
        "wig" | "wiggle" if !compressed => (TrackSpecKind::Wig, TrackKind::Quantitative),
        "bedpe" if !compressed => (TrackSpecKind::BedPe, TrackKind::Interaction),
        "interact" if !compressed => (TrackSpecKind::Interact, TrackKind::Interaction),
        "seg" | "cbs" if !compressed => (TrackSpecKind::Seg, TrackKind::CopyNumber),
        "bb" | "bigbed" if !compressed => (TrackSpecKind::BigBed, TrackKind::Feature),
        "biggenepred" if !compressed => (TrackSpecKind::BigGenePred, TrackKind::GeneModel),
        "bignarrowpeak" if !compressed => (TrackSpecKind::BigNarrowPeak, TrackKind::Feature),
        _ => anyhow::bail!("unsupported track format {}", path.display()),
    };
    Ok(inferred)
}

fn track_source(path: &std::path::Path) -> TrackSource {
    let value = path.display().to_string();
    if value.starts_with("http://") || value.starts_with("https://") {
        TrackSource::Remote { url: value }
    } else {
        TrackSource::Local { path: value }
    }
}

fn apply_accessibility_preferences(context: &egui::Context, settings: &DesktopSettings) {
    context.set_theme(egui::Theme::Light);
    context.set_zoom_factor(f32::from(settings.interface_scale_percent) / 100.0);
    let mut visuals = egui::Visuals::light();
    if settings.high_contrast {
        visuals.override_text_color = Some(egui::Color32::BLACK);
        visuals.faint_bg_color = egui::Color32::WHITE;
        visuals.extreme_bg_color = egui::Color32::WHITE;
        visuals.widgets.noninteractive.bg_stroke = egui::Stroke::new(1.25, egui::Color32::BLACK);
        visuals.widgets.inactive.bg_stroke = egui::Stroke::new(1.5, egui::Color32::BLACK);
        visuals.widgets.hovered.bg_stroke = egui::Stroke::new(2.0, egui::Color32::BLACK);
        visuals.widgets.active.bg_stroke = egui::Stroke::new(2.0, egui::Color32::BLACK);
        visuals.widgets.open.bg_stroke = egui::Stroke::new(2.0, egui::Color32::BLACK);
        visuals.selection.bg_fill = egui::Color32::from_rgb(0, 64, 160);
        visuals.selection.stroke = egui::Stroke::new(2.0, egui::Color32::WHITE);
    }
    context.set_visuals(visuals);
    context.style_mut_of(egui::Theme::Light, |style| {
        style.animation_time = if settings.reduced_motion { 0.0 } else { 0.2 };
    });
    if settings.reduced_motion {
        context.clear_animations();
    }
}

fn main() -> Result<()> {
    let process_started = Instant::now();
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "rgv=info".into()),
        )
        .init();

    let mut options = LaunchOptions::parse();
    options.load_session()?;
    let mut run_marker = RunMarker::start(
        options
            .settings_path
            .as_deref()
            .unwrap_or_else(|| Path::new("rgv-settings.json")),
    );
    options.recovered_unclean_exit = run_marker.previous_unclean_exit();
    if options.recovered_unclean_exit {
        options.recovery_candidates = discover_recovery_candidates(
            options
                .settings_path
                .as_deref()
                .unwrap_or_else(|| Path::new("rgv-settings.json")),
        );
    }
    let event_loop = match EventLoop::new().context("failed to create native event loop") {
        Ok(event_loop) => event_loop,
        Err(error) => {
            run_marker.finish();
            return Err(error);
        }
    };
    event_loop.set_control_flow(ControlFlow::Wait);
    let result = event_loop
        .run_app(&mut Application {
            viewer: None,
            options,
            process_started,
        })
        .context("RGV event loop failed");
    run_marker.finish();
    result
}

struct RunMarker {
    path: Option<PathBuf>,
    previous_unclean_exit: bool,
}

impl RunMarker {
    fn start(settings_path: &Path) -> Self {
        let marker_path = settings_path.with_file_name("rgv-running.marker");
        let previous_unclean_exit = marker_path.exists();
        let parent_ready = marker_path.parent().is_none_or(|parent| {
            if parent.as_os_str().is_empty() {
                return true;
            }
            if let Err(error) = std::fs::create_dir_all(parent) {
                tracing::warn!(%error, "could not create run-marker directory");
                return false;
            }
            true
        });
        let path = parent_ready
            .then(|| {
                let marker = format!("pid={}\n", std::process::id());
                match std::fs::write(&marker_path, marker) {
                    Ok(()) => Some(marker_path.clone()),
                    Err(error) => {
                        tracing::warn!(%error, "could not create unclean-exit marker");
                        None
                    }
                }
            })
            .flatten();
        Self {
            path,
            previous_unclean_exit,
        }
    }

    const fn previous_unclean_exit(&self) -> bool {
        self.previous_unclean_exit
    }

    fn finish(&mut self) {
        if let Some(path) = self.path.take()
            && let Err(error) = std::fs::remove_file(path)
        {
            tracing::warn!(%error, "could not remove clean-exit marker");
        }
    }
}

struct Application {
    viewer: Option<Viewer>,
    options: LaunchOptions,
    process_started: Instant,
}

struct ExportTask {
    path: PathBuf,
    automation_command: Option<usize>,
    worker: JoinHandle<std::io::Result<()>>,
}

struct SessionSaveTask {
    path: PathBuf,
    kind: SessionSaveKind,
    automation_command: Option<usize>,
    worker: JoinHandle<std::result::Result<(), String>>,
}

struct AutomationRunner {
    commands: VecDeque<(usize, AutomationCommand)>,
    results: Vec<AutomationCommandResult>,
    waiting: Option<AutomationWait>,
    report_path: Option<PathBuf>,
    report_worker: Option<JoinHandle<std::result::Result<(), String>>>,
    control_reply: Option<std::sync::mpsc::SyncSender<AutomationRunReport>>,
    exit_after_report: bool,
    finished: bool,
    run_started: Instant,
    process_started: Option<Instant>,
    active_command: Option<ActiveAutomationCommand>,
    first_frame_ms: Option<f64>,
    first_settled_ms: Option<f64>,
    environment: AutomationEnvironmentTelemetry,
    presented_frames: u64,
    frame_samples_ms: Vec<f64>,
    frame_samples_dropped: u64,
    gpu: AutomationGpuTelemetry,
}

struct ActiveAutomationCommand {
    index: usize,
    name: &'static str,
    started: Instant,
}

#[derive(Clone, Copy)]
enum AutomationWait {
    Settled {
        command_index: usize,
        deadline: Instant,
    },
    File {
        command_index: usize,
    },
    Reference {
        command_index: usize,
        deadline: Instant,
    },
    AlignmentTrack {
        command_index: usize,
        track_id: TrackId,
        deadline: Instant,
    },
    AuxiliaryTrack {
        command_index: usize,
        track_id: TrackId,
        deadline: Instant,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum AutomationAuxiliaryOpenState {
    Pending,
    Ready,
    Failed(String),
}

enum AutomationExecution {
    Complete {
        message: String,
        data: serde_json::Value,
    },
    Wait(AutomationWait),
    Failed {
        code: AutomationErrorCode,
        message: String,
    },
}

impl AutomationRunner {
    #[cfg(test)]
    fn new(batch: AutomationBatch, report_path: PathBuf) -> Self {
        Self::new_with_telemetry(
            batch,
            report_path,
            None,
            AutomationEnvironmentTelemetry::default(),
        )
    }

    fn new_with_telemetry(
        batch: AutomationBatch,
        report_path: PathBuf,
        process_started: Option<Instant>,
        environment: AutomationEnvironmentTelemetry,
    ) -> Self {
        Self {
            commands: batch.commands.into_iter().enumerate().collect(),
            results: Vec::new(),
            waiting: None,
            report_path: Some(report_path),
            report_worker: None,
            control_reply: None,
            exit_after_report: false,
            finished: false,
            run_started: Instant::now(),
            process_started,
            active_command: None,
            first_frame_ms: None,
            first_settled_ms: None,
            environment,
            presented_frames: 0,
            frame_samples_ms: Vec::new(),
            frame_samples_dropped: 0,
            gpu: AutomationGpuTelemetry::default(),
        }
    }

    fn for_control(request: ControlRequest) -> Self {
        Self {
            commands: request.batch.commands.into_iter().enumerate().collect(),
            results: Vec::new(),
            waiting: None,
            report_path: None,
            report_worker: None,
            control_reply: Some(request.reply),
            exit_after_report: false,
            finished: false,
            run_started: Instant::now(),
            process_started: None,
            active_command: None,
            first_frame_ms: None,
            first_settled_ms: None,
            environment: AutomationEnvironmentTelemetry::default(),
            presented_frames: 0,
            frame_samples_ms: Vec::new(),
            frame_samples_dropped: 0,
            gpu: AutomationGpuTelemetry::default(),
        }
    }

    fn begin_command(&mut self, index: usize, name: &'static str, now: Instant) {
        self.active_command = Some(ActiveAutomationCommand {
            index,
            name,
            started: now,
        });
    }

    fn record_first_settled(&mut self, now: Instant) {
        if self.first_settled_ms.is_none()
            && let Some(process_started) = self.process_started
        {
            self.first_settled_ms = Some(milliseconds_between(process_started, now));
        }
    }

    fn record_frame(
        &mut self,
        now: Instant,
        frame_ms: f64,
        prepared: Option<PrepareStats>,
        surface: [u32; 2],
        scale_factor: f64,
    ) {
        self.presented_frames = self.presented_frames.saturating_add(1);
        if self.frame_samples_ms.len() < MAX_AUTOMATION_FRAME_SAMPLES {
            self.frame_samples_ms.push(frame_ms);
        } else {
            self.frame_samples_dropped = self.frame_samples_dropped.saturating_add(1);
        }
        self.environment.surface_width_pixels = surface[0];
        self.environment.surface_height_pixels = surface[1];
        self.environment.scale_factor = scale_factor;
        if self.first_frame_ms.is_none()
            && let Some(process_started) = self.process_started
        {
            self.first_frame_ms = Some(milliseconds_between(process_started, now));
        }
        let Some(prepared) = prepared else {
            return;
        };
        self.gpu.prepared_frames = self.gpu.prepared_frames.saturating_add(1);
        self.gpu.peak_instances = self.gpu.peak_instances.max(prepared.total_instances);
        self.gpu.peak_uploaded_bytes = self.gpu.peak_uploaded_bytes.max(prepared.uploaded_bytes);
        self.gpu.total_uploaded_bytes = self
            .gpu
            .total_uploaded_bytes
            .saturating_add(prepared.uploaded_bytes as u64);
        self.gpu.uploaded_frames = self
            .gpu
            .uploaded_frames
            .saturating_add(u64::from(prepared.uploaded_bytes > 0));
        self.gpu.buffer_reallocations = self
            .gpu
            .buffer_reallocations
            .saturating_add(u64::from(prepared.buffer_reallocated));
        self.gpu.truncated_frames = self
            .gpu
            .truncated_frames
            .saturating_add(u64::from(prepared.truncated));
    }

    fn report(&self, now: Instant) -> AutomationRunReport {
        let (median_ms, p95_ms, maximum_ms) = frame_summary(&self.frame_samples_ms);
        AutomationRunReport {
            schema_version: AUTOMATION_SCHEMA_VERSION,
            succeeded: self
                .results
                .iter()
                .all(|result| result.status == AutomationCommandStatus::Succeeded),
            results: self.results.clone(),
            telemetry: AutomationRunTelemetry {
                run_elapsed_ms: milliseconds_between(self.run_started, now),
                startup_to_first_frame_ms: self.first_frame_ms,
                startup_to_first_settled_ms: self.first_settled_ms,
                environment: self.environment.clone(),
                frames: AutomationFrameTelemetry {
                    presented_frames: self.presented_frames,
                    samples_ms: self.frame_samples_ms.clone(),
                    samples_dropped: self.frame_samples_dropped,
                    median_ms,
                    p95_ms,
                    maximum_ms,
                },
                gpu: self.gpu.clone(),
            },
        }
    }

    fn finish_command(
        &mut self,
        command_index: usize,
        outcome: std::result::Result<(String, serde_json::Value), (AutomationErrorCode, String)>,
    ) -> bool {
        if self
            .active_command
            .as_ref()
            .is_some_and(|active| active.index != command_index)
        {
            return false;
        }
        if let Some(waiting_index) = self.waiting.as_ref().map(|waiting| match waiting {
            AutomationWait::Settled { command_index, .. }
            | AutomationWait::File { command_index }
            | AutomationWait::Reference { command_index, .. }
            | AutomationWait::AlignmentTrack { command_index, .. }
            | AutomationWait::AuxiliaryTrack { command_index, .. } => *command_index,
        }) && waiting_index != command_index
        {
            return false;
        }
        self.waiting = None;
        let active = self.active_command.take();
        let command = active.as_ref().map_or("", |active| active.name).to_owned();
        let elapsed_ms = active.map_or(0.0, |active| {
            active.started.elapsed().as_secs_f64() * 1_000.0
        });
        match outcome {
            Ok((message, data)) => self.results.push(AutomationCommandResult {
                command_index,
                command,
                status: AutomationCommandStatus::Succeeded,
                error_code: None,
                message,
                data,
                elapsed_ms,
            }),
            Err((code, message)) => {
                self.results.push(AutomationCommandResult {
                    command_index,
                    command,
                    status: AutomationCommandStatus::Failed,
                    error_code: Some(code),
                    message,
                    data: serde_json::Value::Null,
                    elapsed_ms,
                });
                for (index, skipped) in self.commands.drain(..) {
                    self.results.push(AutomationCommandResult {
                        command_index: index,
                        command: skipped.name().to_owned(),
                        status: AutomationCommandStatus::Skipped,
                        error_code: None,
                        message: "Skipped after an earlier command failed".to_owned(),
                        data: serde_json::Value::Null,
                        elapsed_ms: 0.0,
                    });
                }
            }
        }
        true
    }
}

fn milliseconds_between(start: Instant, end: Instant) -> f64 {
    end.saturating_duration_since(start).as_secs_f64() * 1_000.0
}

fn frame_summary(samples: &[f64]) -> (Option<f64>, Option<f64>, Option<f64>) {
    if samples.is_empty() {
        return (None, None, None);
    }
    let mut sorted = samples.to_vec();
    sorted.sort_by(f64::total_cmp);
    let median = sorted[sorted.len() / 2];
    let p95_index = ((sorted.len() as f64 * 0.95).ceil() as usize).clamp(1, sorted.len()) - 1;
    (
        Some(median),
        Some(sorted[p95_index]),
        sorted.last().copied(),
    )
}

fn automation_failure(
    code: AutomationErrorCode,
    error: impl std::fmt::Display,
) -> AutomationExecution {
    AutomationExecution::Failed {
        code,
        message: error.to_string(),
    }
}

fn automation_bool(value: &serde_json::Value, key: &str) -> Result<bool> {
    value
        .as_bool()
        .with_context(|| format!("{key} must be a boolean"))
}

fn automation_u64(value: &serde_json::Value, key: &str) -> Result<u64> {
    value
        .as_u64()
        .with_context(|| format!("{key} must be a non-negative integer"))
}

fn automation_optional_u64(value: &serde_json::Value, key: &str) -> Result<Option<u64>> {
    if value.is_null() {
        Ok(None)
    } else {
        automation_u64(value, key).map(Some)
    }
}

fn automation_u8(value: u64, key: &str) -> Result<u8> {
    u8::try_from(value).with_context(|| format!("{key} must be no greater than {}", u8::MAX))
}

fn automation_u32(value: u64, key: &str) -> Result<u32> {
    u32::try_from(value).with_context(|| format!("{key} must be no greater than {}", u32::MAX))
}

fn automation_f32(value: &serde_json::Value, key: &str) -> Result<f32> {
    let number = value
        .as_f64()
        .with_context(|| format!("{key} must be a number"))?;
    anyhow::ensure!(number.is_finite(), "{key} must be finite");
    anyhow::ensure!(
        number >= f64::from(f32::MIN) && number <= f64::from(f32::MAX),
        "{key} is outside the supported numeric range"
    );
    Ok(number as f32)
}

fn automation_name(value: &serde_json::Value, key: &str) -> Result<String> {
    let name = value
        .as_str()
        .with_context(|| format!("{key} must be a string"))?;
    anyhow::ensure!(!name.trim().is_empty(), "{key} must not be empty");
    anyhow::ensure!(name.len() <= 4_096, "{key} exceeds 4096 bytes");
    Ok(name.to_owned())
}

fn automation_optional_name(value: &serde_json::Value, key: &str) -> Result<Option<String>> {
    if value.is_null() {
        Ok(None)
    } else {
        automation_name(value, key).map(Some)
    }
}

fn parse_automation_sam_tag(tag: &str) -> Result<[u8; 2]> {
    let bytes = tag.as_bytes();
    anyhow::ensure!(
        bytes.len() == 2 && bytes[0].is_ascii_alphabetic() && bytes[1].is_ascii_alphanumeric(),
        "tag must be a valid two-character SAM tag"
    );
    Ok([bytes[0], bytes[1]])
}

fn logical_surface_dimension(physical: u32, scale_factor: f64) -> u32 {
    (f64::from(physical) / scale_factor.max(f64::EPSILON))
        .round()
        .clamp(1.0, f64::from(u32::MAX)) as u32
}

fn cropped_display_list(display: &DisplayList, bounds: egui::Rect) -> DisplayList {
    let mut cropped = DisplayList::default();
    for rectangle in &display.rectangles {
        let left = rectangle.x.max(bounds.left());
        let top = rectangle.y.max(bounds.top());
        let right = (rectangle.x + rectangle.width).min(bounds.right());
        let bottom = (rectangle.y + rectangle.height).min(bounds.bottom());
        if right > left && bottom > top {
            cropped.rectangles.push(RectPrimitive {
                x: left - bounds.left(),
                y: top - bounds.top(),
                width: right - left,
                height: bottom - top,
                color: rectangle.color,
                object_id: rectangle.object_id,
            });
        }
    }
    cropped.texts.extend(
        display
            .texts
            .iter()
            .filter(|text| {
                text.x >= bounds.left()
                    && text.x < bounds.right()
                    && text.y >= bounds.top()
                    && text.y < bounds.bottom()
            })
            .cloned()
            .map(|mut text| {
                text.x -= bounds.left();
                text.y -= bounds.top();
                text
            }),
    );
    cropped
}

fn automation_snapshot_metadata(
    assembly_name: &str,
    panels: &PanelWorkspace,
    alignment_tracks: &[AlignmentTrackController],
    tracks: &TrackCollection,
    scope: &str,
) -> String {
    let mut metadata = format!(
        "RGV {} snapshot; scope {scope}; genome {}; ",
        env!("CARGO_PKG_VERSION"),
        sanitized_single_line(assembly_name, 4_096),
    );
    metadata.push_str("loci ");
    for (index, panel) in panels.iter().enumerate() {
        if index > 0 {
            metadata.push_str(", ");
        }
        let interval = panel.viewport.interval();
        let _ = write!(
            metadata,
            "{}:{}-{}",
            sanitized_single_line(&panel.contig_name, 4_096),
            interval.start().saturating_add(1),
            interval.end()
        );
    }
    metadata.push_str("; visible tracks ");
    let mut first = true;
    for (id, name) in alignment_tracks
        .iter()
        .filter(|track| track.config.visible)
        .map(|track| (track.config.id, track.config.name.as_str()))
        .chain(
            tracks
                .tracks()
                .iter()
                .filter(|track| track.visible)
                .map(|track| (track.id, track.name.as_str())),
        )
    {
        if !first {
            metadata.push_str(", ");
        }
        first = false;
        let _ = write!(
            metadata,
            "{}:{}",
            id.get(),
            sanitized_single_line(name, 4_096)
        );
    }
    metadata
}

fn display_list_svg_export(
    display: &DisplayList,
    width: u32,
    height: u32,
    metadata: &str,
) -> String {
    let mut output = format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{width}\" height=\"{height}\" viewBox=\"0 0 {width} {height}\">\n<metadata>{}</metadata>\n<rect width=\"100%\" height=\"100%\" fill=\"white\"/>\n",
        xml_escape(metadata),
    );
    let mut truncated = false;
    for rectangle in &display.rectangles {
        let red = (rectangle.color.red.clamp(0.0, 1.0) * 255.0).round() as u8;
        let green = (rectangle.color.green.clamp(0.0, 1.0) * 255.0).round() as u8;
        let blue = (rectangle.color.blue.clamp(0.0, 1.0) * 255.0).round() as u8;
        let element = format!(
            "<rect x=\"{:.2}\" y=\"{:.2}\" width=\"{:.2}\" height=\"{:.2}\" fill=\"rgb({red},{green},{blue})\" fill-opacity=\"{:.3}\"/>\n",
            rectangle.x,
            rectangle.y,
            rectangle.width,
            rectangle.height,
            rectangle.color.alpha.clamp(0.0, 1.0),
        );
        if output
            .len()
            .saturating_add(element.len())
            .saturating_add(64)
            > MAX_AUTOMATION_EXPORT_BYTES
        {
            truncated = true;
            break;
        }
        output.push_str(&element);
    }
    if !truncated {
        for text in &display.texts {
            let red = (text.color.red.clamp(0.0, 1.0) * 255.0).round() as u8;
            let green = (text.color.green.clamp(0.0, 1.0) * 255.0).round() as u8;
            let blue = (text.color.blue.clamp(0.0, 1.0) * 255.0).round() as u8;
            let element = format!(
                "<text x=\"{:.2}\" y=\"{:.2}\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"monospace\" font-size=\"{:.2}\" fill=\"rgb({red},{green},{blue})\">{}</text>\n",
                text.x,
                text.y,
                text.font_size,
                xml_escape(&text.text),
            );
            if output
                .len()
                .saturating_add(element.len())
                .saturating_add(64)
                > MAX_AUTOMATION_EXPORT_BYTES
            {
                truncated = true;
                break;
            }
            output.push_str(&element);
        }
    }
    if truncated {
        output.push_str("<!-- export truncated at the declared byte limit -->\n");
    }
    output.push_str("</svg>\n");
    output
}

fn automation_track_names_export(
    assembly_name: &str,
    panels: &PanelWorkspace,
    alignment_tracks: &[AlignmentTrackController],
    tracks: &TrackCollection,
) -> String {
    let mut output = format!(
        "# RGV {} track-name export\n# genome\t{}\n# panel_count\t{}\ntrack_id\tkind\tname\tsample_key\tvisible\n",
        env!("CARGO_PKG_VERSION"),
        sanitized_tsv_field(assembly_name, 4_096),
        panels.len(),
    );
    for track in alignment_tracks {
        let _ = writeln!(
            output,
            "{}\talignment\t{}\t{}\t{}",
            track.config.id.get(),
            sanitized_tsv_field(&track.config.name, 4_096),
            track
                .config
                .sample_key
                .as_deref()
                .map_or_else(String::new, |value| sanitized_tsv_field(value, 4_096)),
            track.config.visible,
        );
    }
    for track in tracks.tracks() {
        let _ = writeln!(
            output,
            "{}\t{}\t{}\t{}\t{}",
            track.id.get(),
            format!("{:?}", track.kind).to_ascii_lowercase(),
            sanitized_tsv_field(&track.name, 4_096),
            track
                .sample_key
                .as_deref()
                .map_or_else(String::new, |value| sanitized_tsv_field(value, 4_096)),
            track.visible,
        );
    }
    output
}

fn automation_export_header(
    kind: &str,
    assembly: &str,
    contig: &str,
    interval: GenomicInterval,
) -> String {
    format!(
        "# RGV {} {kind} export v1\n# genome\t{}\n# locus\t{}:{}-{}\n# coordinates\tstart is one-based; end is one-based inclusive; internal intervals are zero-based half-open\n# byte_limit\t{MAX_AUTOMATION_EXPORT_BYTES}\n",
        env!("CARGO_PKG_VERSION"),
        sanitized_tsv_field(assembly, 4_096),
        sanitized_tsv_field(contig, 4_096),
        interval.start().saturating_add(1),
        interval.end(),
    )
}

fn push_automation_export_line(output: &mut String, line: &str) -> bool {
    let required = line.len().saturating_add(1);
    if output.len().saturating_add(required) <= MAX_AUTOMATION_EXPORT_BYTES {
        output.push_str(line);
        output.push('\n');
        return true;
    }
    let marker = "# export_truncated\tbyte_limit_reached\n";
    if output.len().saturating_add(marker.len()) <= MAX_AUTOMATION_EXPORT_BYTES {
        output.push_str(marker);
    }
    false
}

fn automation_alignments_export(
    assembly: &str,
    contig: &str,
    interval: GenomicInterval,
    tracks: &[AutomationAlignmentExportTrack],
) -> String {
    let mut output = automation_export_header("alignment", assembly, contig, interval);
    if !push_automation_export_line(
        &mut output,
        "track_id\ttrack_name\tcontig\tstart\tend\tread_name\tflags\tmapq\tcigar\tmate_contig_id\tmate_start\ttemplate_length",
    ) {
        return output;
    }
    for track in tracks {
        let query = &track.query;
        let _ = push_automation_export_line(
            &mut output,
            &format!(
                "# track_provenance\t{}\t{}\trecords_seen={}\trecords_eligible={}\trecords_retained={}\tretained_truncated={}",
                track.id.get(),
                sanitized_tsv_field(&track.name, 4_096),
                query.stats.records_seen,
                query.stats.records_eligible,
                query.batch.len(),
                query.stats.truncated,
            ),
        );
        for index in 0..query.batch.len() {
            let start = query.batch.starts[index];
            let end = query.batch.ends[index];
            if start >= interval.end() || end <= interval.start() {
                continue;
            }
            let line = format!(
                "{}\t{}\t{}\t{}\t{}\t{}\t0x{:04x}\t{}\t{}\t{}\t{}\t{}",
                track.id.get(),
                sanitized_tsv_field(&track.name, 4_096),
                sanitized_tsv_field(contig, 4_096),
                start.saturating_add(1),
                end,
                sanitized_tsv_field(
                    &String::from_utf8_lossy(query.batch.read_name(index).unwrap_or_default()),
                    1_024,
                ),
                query.batch.flags[index].bits(),
                query.batch.mapping_qualities[index]
                    .map_or_else(|| ".".to_owned(), |value| value.to_string()),
                format_cigar(query.batch.cigar(index).unwrap_or_default()),
                query.batch.mate_contigs[index]
                    .map_or_else(|| ".".to_owned(), |value| value.get().to_string()),
                query.batch.mate_starts[index].map_or_else(
                    || ".".to_owned(),
                    |value| value.saturating_add(1).to_string()
                ),
                query.batch.template_lengths[index],
            );
            if !push_automation_export_line(&mut output, &line) {
                return output;
            }
        }
    }
    output
}

fn automation_pileup_export(
    assembly: &str,
    contig: &str,
    interval: GenomicInterval,
    tracks: &[AutomationAlignmentExportTrack],
) -> String {
    let mut output = automation_export_header("pileup", assembly, contig, interval);
    if !push_automation_export_line(
        &mut output,
        "track_id\ttrack_name\tcontig\tstart\tend\tdepth\tforward_depth\treverse_depth\tA\tC\tG\tT\tN\tinsertion\tdeletion\tmean_base_quality\tmean_mapping_quality",
    ) {
        return output;
    }
    for track in tracks {
        let query = &track.query;
        let provenance = query.pileup.provenance;
        let _ = push_automation_export_line(
            &mut output,
            &format!(
                "# track_provenance\t{}\t{}\teligible_records={}\trendered_records={}\tall_eligible_records={}\talleles_available={}\toverlap_collapse_complete={}",
                track.id.get(),
                sanitized_tsv_field(&track.name, 4_096),
                provenance.eligible_records,
                provenance.rendered_records,
                provenance.all_eligible_records,
                provenance.allele_observations_available,
                provenance.overlap_collapse_complete,
            ),
        );
        for (index, bin) in query.pileup.bins.iter().copied().enumerate() {
            let Some(bin_interval) = query.pileup.bin_interval(query.interval, index) else {
                continue;
            };
            if !bin_interval.overlaps(interval) {
                continue;
            }
            let line = format!(
                "{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
                track.id.get(),
                sanitized_tsv_field(&track.name, 4_096),
                sanitized_tsv_field(contig, 4_096),
                bin_interval.start().saturating_add(1),
                bin_interval.end(),
                bin.depth,
                bin.forward_depth,
                bin.reverse_depth,
                bin.alleles.a,
                bin.alleles.c,
                bin.alleles.g,
                bin.alleles.t,
                bin.alleles.n,
                bin.alleles.insertion,
                bin.alleles.deletion,
                bin.mean_base_quality()
                    .map_or_else(|| ".".to_owned(), |value| format!("{value:.4}")),
                bin.mean_mapping_quality()
                    .map_or_else(|| ".".to_owned(), |value| format!("{value:.4}")),
            );
            if !push_automation_export_line(&mut output, &line) {
                return output;
            }
        }
    }
    output
}

fn automation_modifications_export(
    assembly: &str,
    contig: &str,
    interval: GenomicInterval,
    tracks: &[AutomationAlignmentExportTrack],
) -> String {
    let mut output = automation_export_header("modified-base", assembly, contig, interval);
    if !push_automation_export_line(
        &mut output,
        "track_id\ttrack_name\tcontig\tstart\tend\tcanonical_base\tmodification_code\tmodification_strand\timplicit_mode\thaplotype\tmodified_calls\tcanonical_observations\tforward_modified_calls\treverse_modified_calls\traw_fraction\tweighted_fraction\tmean_probability\tmissing_probability_calls",
    ) {
        return output;
    }
    for track in tracks {
        let query = &track.query;
        let summary = &query.pileup.modifications;
        let provenance = summary.provenance;
        let _ = push_automation_export_line(
            &mut output,
            &format!(
                "# track_provenance\t{}\t{}\teligible_records={}\ttagged_records={}\tdecoded_calls={}\tmalformed_records={}\tunavailable_records={}\tdropped_series={}\tall_eligible_records={}",
                track.id.get(),
                sanitized_tsv_field(&track.name, 4_096),
                provenance.eligible_records,
                provenance.records_with_modification_tags,
                provenance.decoded_calls,
                provenance.malformed_records,
                provenance.unavailable_records,
                provenance.dropped_series,
                provenance.all_eligible_records,
            ),
        );
        for series in &summary.series {
            for (index, bin) in series.bins.iter().copied().enumerate() {
                if bin.canonical_observations == 0
                    && bin.modified_calls == 0
                    && bin.missing_probability_calls == 0
                {
                    continue;
                }
                let Some(bin_interval) = summary.bin_interval(query.interval, index) else {
                    continue;
                };
                if !bin_interval.overlaps(interval) {
                    continue;
                }
                let line = format!(
                    "{}\t{}\t{}\t{}\t{}\t{}\t{}\t{:?}\t{:?}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
                    track.id.get(),
                    sanitized_tsv_field(&track.name, 4_096),
                    sanitized_tsv_field(contig, 4_096),
                    bin_interval.start().saturating_add(1),
                    bin_interval.end(),
                    char::from(series.key.canonical_base),
                    modification_code_label(series.key.code),
                    series.key.modification_strand,
                    series.key.implicit_mode,
                    series
                        .key
                        .haplotype
                        .map_or_else(|| ".".to_owned(), |value| value.to_string()),
                    bin.modified_calls,
                    bin.canonical_observations,
                    bin.forward_modified_calls,
                    bin.reverse_modified_calls,
                    bin.raw_fraction()
                        .map_or_else(|| ".".to_owned(), |value| format!("{value:.6}")),
                    bin.weighted_fraction()
                        .map_or_else(|| ".".to_owned(), |value| format!("{value:.6}")),
                    bin.mean_probability()
                        .map_or_else(|| ".".to_owned(), |value| format!("{value:.4}")),
                    bin.missing_probability_calls,
                );
                if !push_automation_export_line(&mut output, &line) {
                    return output;
                }
            }
        }
    }
    output
}

fn automation_junctions_export(
    assembly: &str,
    contig: &str,
    interval: GenomicInterval,
    tracks: &[AutomationAlignmentExportTrack],
) -> String {
    let mut output = automation_export_header("junction", assembly, contig, interval);
    if !push_automation_export_line(
        &mut output,
        "track_id\ttrack_name\tcontig\tstart\tend\tdepth\tminimum_left_flank\tminimum_right_flank\tmaximum_left_flank\tmaximum_right_flank\tpositive_depth\tnegative_depth\tunknown_depth\ttagged_positive_depth\ttagged_negative_depth\tfallback_positive_depth\tfallback_negative_depth\tinvalid_strand_depth",
    ) {
        return output;
    }
    for track in tracks {
        let query = &track.query;
        let provenance = query.junctions.provenance;
        let _ = push_automation_export_line(
            &mut output,
            &format!(
                "# track_provenance\t{}\t{}\teligible_records={}\tspliced_records={}\tobservations_examined={}\tobservations_retained={}\tdropped_distinct={}\tall_eligible_records={}",
                track.id.get(),
                sanitized_tsv_field(&track.name, 4_096),
                provenance.eligible_records,
                provenance.spliced_records,
                provenance.junction_observations_examined,
                provenance.junction_observations_retained,
                provenance.dropped_distinct_junctions,
                provenance.all_eligible_records,
            ),
        );
        for junction in &query.junctions.junctions {
            if junction.start >= interval.end() || junction.end <= interval.start() {
                continue;
            }
            let line = format!(
                "{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
                track.id.get(),
                sanitized_tsv_field(&track.name, 4_096),
                sanitized_tsv_field(contig, 4_096),
                junction.start.saturating_add(1),
                junction.end,
                junction.depth,
                junction.minimum_left_flank,
                junction.minimum_right_flank,
                junction.maximum_left_flank,
                junction.maximum_right_flank,
                junction.positive_depth,
                junction.negative_depth,
                junction.unknown_depth,
                junction.tagged_positive_depth,
                junction.tagged_negative_depth,
                junction.fallback_positive_depth,
                junction.fallback_negative_depth,
                junction.invalid_strand_depth,
            );
            if !push_automation_export_line(&mut output, &line) {
                return output;
            }
        }
    }
    output
}

#[allow(clippy::too_many_lines)]
fn automation_variants_export(
    assembly: &str,
    contig: &str,
    interval: GenomicInterval,
    snapshots: &[TrackSnapshot],
) -> String {
    let mut output = automation_export_header("variant", assembly, contig, interval);
    for line in [
        "record\ttrack_id\ttrack_name\tcontig\tstart\tend\tid\tref\talt\tqual\tfilters\ttypes",
        "info\ttrack_id\trecord_ordinal\tkey\tvalue\tfield_truncated",
        "genotype\ttrack_id\trecord_ordinal\tsample\tgenotype\tgroup\tformat_fields",
    ] {
        if !push_automation_export_line(&mut output, line) {
            return output;
        }
    }
    for snapshot in snapshots {
        let TrackSnapshotData::Variants(query) = &snapshot.data else {
            continue;
        };
        let provenance = query.provenance;
        let _ = push_automation_export_line(
            &mut output,
            &format!(
                "# track_provenance\t{}\t{}\trecords_examined={}\trecords_filtered={}\trecords_truncated={}\ttotal_samples={}\tselected_samples={}\tgenotype_cells_omitted={}",
                snapshot.id.get(),
                sanitized_tsv_field(&snapshot.name, 4_096),
                provenance.records_examined,
                provenance.records_filtered,
                provenance.records_truncated,
                provenance.total_samples,
                provenance.selected_samples,
                provenance.genotype_cells_omitted,
            ),
        );
        for (ordinal, record) in query.records.iter().enumerate() {
            if record.start >= interval.end() || record.end <= interval.start() {
                continue;
            }
            let filters = if record.filters.is_empty() {
                "PASS".to_owned()
            } else {
                record.filters.join(";")
            };
            let line = format!(
                "record\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
                snapshot.id.get(),
                sanitized_tsv_field(&snapshot.name, 4_096),
                sanitized_tsv_field(&record.contig, 4_096),
                record.start.saturating_add(1),
                record.end,
                tsv_cell(record.id.as_deref().unwrap_or(".")),
                tsv_cell(&bounded_variant_allele(&record.reference)),
                tsv_cell(
                    &record
                        .alternates
                        .iter()
                        .map(|allele| bounded_variant_allele(allele))
                        .collect::<Vec<_>>()
                        .join(",")
                ),
                record
                    .quality
                    .map_or_else(|| ".".to_owned(), |value| value.to_string()),
                tsv_cell(&filters),
                tsv_cell(
                    &record
                        .variant_types
                        .iter()
                        .map(format_variant_type)
                        .collect::<Vec<_>>()
                        .join(",")
                ),
            );
            if !push_automation_export_line(&mut output, &line) {
                return output;
            }
            for field in &record.info {
                let value = bounded_variant_export_field(field);
                let line = format!(
                    "info\t{}\t{}\t{}\t{}\t{}",
                    snapshot.id.get(),
                    ordinal,
                    tsv_cell(&field.key),
                    tsv_cell(&value),
                    field.truncated || value.ends_with('…'),
                );
                if !push_automation_export_line(&mut output, &line) {
                    return output;
                }
            }
            for genotype in &record.genotypes {
                let sample = query
                    .header
                    .samples
                    .get(genotype.sample_index)
                    .map_or("?", String::as_str);
                let format_fields = genotype
                    .fields
                    .iter()
                    .map(|field| format!("{}={}", field.key, bounded_variant_export_field(field)))
                    .collect::<Vec<_>>()
                    .join(";");
                let line = format!(
                    "genotype\t{}\t{}\t{}\t{}\t{}\t{}",
                    snapshot.id.get(),
                    ordinal,
                    tsv_cell(sample),
                    tsv_cell(&format_genotype(genotype)),
                    variant_genotype_group_label(genotype),
                    tsv_cell(&format_fields),
                );
                if !push_automation_export_line(&mut output, &line) {
                    return output;
                }
            }
        }
    }
    output
}

fn automation_quantitative_export(
    assembly: &str,
    contig: &str,
    interval: GenomicInterval,
    snapshots: &[TrackSnapshot],
) -> String {
    let mut output = automation_export_header("quantitative-window", assembly, contig, interval);
    if !push_automation_export_line(
        &mut output,
        "track_id\ttrack_name\tcontig\tstart\tend\tvalue",
    ) {
        return output;
    }
    for snapshot in snapshots {
        let TrackSnapshotData::Quantitative(query) = &snapshot.data else {
            continue;
        };
        let provenance = query.provenance;
        let _ = push_automation_export_line(
            &mut output,
            &format!(
                "# track_provenance\t{}\t{}\trecords_examined={}\trecords_retained={}\tnon_finite_records={}\trecords_truncated={}",
                snapshot.id.get(),
                sanitized_tsv_field(&snapshot.name, 4_096),
                provenance.records_examined,
                provenance.records_retained,
                provenance.non_finite_records,
                provenance.records_truncated,
            ),
        );
        if let Some(rgv_hts::QuantitativeSourceMetadata::Tdf(metadata)) = &query.source_metadata {
            let _ = push_automation_export_line(
                &mut output,
                &format!(
                    "# tdf_source\t{}\tchannel={}\tchannel_index={}\tchannel_count={}\tdataset={}\tversion={}\tgenome={}\tcompressed={}",
                    snapshot.id.get(),
                    tsv_cell(&metadata.selected_track_name),
                    metadata.selected_track_index,
                    metadata.track_count,
                    tsv_cell(&metadata.dataset),
                    metadata.version,
                    tsv_cell(metadata.genome_id.as_deref().unwrap_or(".")),
                    metadata.compressed,
                ),
            );
        }
        for record in &query.records {
            if record.start >= interval.end() || record.end <= interval.start() {
                continue;
            }
            let line = format!(
                "{}\t{}\t{}\t{}\t{}\t{}",
                snapshot.id.get(),
                sanitized_tsv_field(&snapshot.name, 4_096),
                sanitized_tsv_field(contig, 4_096),
                record.start.saturating_add(1),
                record.end,
                record.value,
            );
            if !push_automation_export_line(&mut output, &line) {
                return output;
            }
        }
    }
    output
}

fn automation_inspector_export(inspector: &InspectorSnapshot) -> String {
    let mut output = format!(
        "# RGV {} selected evidence export v1\n# byte_limit\t{MAX_AUTOMATION_EXPORT_BYTES}\nsection\tkey\tvalue\n",
        env!("CARGO_PKG_VERSION")
    );
    for (key, value) in &inspector.fields {
        if !push_automation_export_line(
            &mut output,
            &format!(
                "detail\t{}\t{}",
                sanitized_tsv_field(key, 4_096),
                sanitized_tsv_field(value, 64 * 1024)
            ),
        ) {
            return output;
        }
    }
    for (key, value) in &inspector.auxiliary {
        if !push_automation_export_line(
            &mut output,
            &format!(
                "tag\t{}\t{}",
                sanitized_tsv_field(key, 4_096),
                sanitized_tsv_field(value, 64 * 1024)
            ),
        ) {
            return output;
        }
    }
    for (key, value) in [
        ("cigar", inspector.cigar.as_deref()),
        ("event_sequence", inspector.event_sequence.as_deref()),
        (
            "read_sequence",
            inspector
                .read_sequence
                .as_ref()
                .map(|sequence| sequence.text.as_str()),
        ),
    ] {
        if let Some(value) = value
            && !push_automation_export_line(
                &mut output,
                &format!(
                    "evidence\t{key}\t{}",
                    sanitized_tsv_field(value, SEQUENCE_COPY_BASES)
                ),
            )
        {
            return output;
        }
    }
    output
}

fn sanitized_single_line(value: &str, maximum_bytes: usize) -> String {
    let mut sanitized = value.replace(['\r', '\n'], " ");
    truncate_string_to_bytes(&mut sanitized, maximum_bytes);
    sanitized
}

fn sanitized_tsv_field(value: &str, maximum_bytes: usize) -> String {
    let mut sanitized = value.replace(['\t', '\r', '\n'], " ");
    truncate_string_to_bytes(&mut sanitized, maximum_bytes);
    sanitized
}

fn create_output_parent(path: &Path) -> std::io::Result<()> {
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        std::fs::create_dir_all(parent)?;
    }
    Ok(())
}

fn atomic_write_text(path: &Path, contents: &str) -> std::result::Result<(), String> {
    create_output_parent(path).map_err(|error| error.to_string())?;
    let parent = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    let mut temporary =
        tempfile::NamedTempFile::new_in(parent).map_err(|error| error.to_string())?;
    temporary
        .write_all(contents.as_bytes())
        .and_then(|()| temporary.flush())
        .and_then(|()| temporary.as_file().sync_all())
        .map_err(|error| error.to_string())?;
    temporary
        .persist(path)
        .map_err(|error| error.error.to_string())?;
    #[cfg(unix)]
    std::fs::File::open(parent)
        .and_then(|directory| directory.sync_all())
        .map_err(|error| error.to_string())?;
    Ok(())
}

