/// Runtime state owned by one genomic view panel.
///
/// Identity, camera, history, query generation, retained data, interaction
/// throttling, and semantic selection stay together so visible panels cannot
/// suppress or replace one another's state.
struct ViewPanelController {
    id: PanelId,
    viewport: Viewport,
    generation_clock: GenerationClock,
    navigation_history: NavigationHistory,
    home_interval: GenomicInterval,
    requested_locus: Option<String>,
    contig_name: String,
    contig_length: u64,
    selected_record: Option<usize>,
    selected_alignment_track: Option<TrackId>,
    selected_alignment_tracks: Vec<TrackId>,
    selected_read_event: Option<ReadEventSelection>,
    selected_pileup_position: Option<u64>,
    selected_modification_position: Option<u64>,
    selected_junction: Option<(u64, u64)>,
    selected_feature: Option<FeatureSelection>,
    selected_variant: Option<VariantSelection>,
    selected_gwas: Option<GwasSelection>,
    selected_quantitative: Option<QuantitativeSelection>,
    selected_copy_number: Option<CopyNumberSelection>,
    selected_mutation: Option<MutationSelection>,
    selected_interaction: Option<InteractionSelection>,
    selected_chain: Option<SelectedSupplementaryChain>,
    pending_read_selection: Option<(TrackId, Vec<u8>)>,
    hovered_record: Option<(TrackId, usize)>,
    hover_inspector_target: Option<HoverInspectorTarget>,
    display_list: DisplayList,
    current_query: Option<Arc<AlignmentQuery>>,
    reference_slice: Option<Arc<ReferenceSlice>>,
    reference_settled_generation: Option<u64>,
    alignment_rows: Option<CachedAlignmentRows>,
    pending_queries: PendingQueries,
    track_snapshots: Vec<TrackSnapshot>,
    track_snapshot_interval: Option<GenomicInterval>,
    track_settled_generation: Option<u64>,
    query_stats: Option<QueryStats>,
    layout_stats: Option<AlignmentLayoutStats>,
    cache_stats: Option<CacheStats>,
    remote_io_stats: Option<RemoteIoStats>,
    available_modification_codes: Vec<ModificationCode>,
    vertical_scroll_points: f32,
    content_bottom_points: f32,
    track_frames: Vec<TrackFrame>,
    selected_track: Option<TrackFrameKey>,
    last_gesture_query_at: Option<Instant>,
}

const INITIAL_PANEL_ID: PanelId = PanelId::new(1);

/// Ordered runtime panel collection. `Deref` intentionally exposes the active
/// panel so the existing single-panel interaction path remains exact while
/// multi-panel rendering addresses every entry explicitly.
struct PanelWorkspace {
    panels: Vec<ViewPanelController>,
    active: usize,
}

impl PanelWorkspace {
    fn new(initial: ViewPanelController) -> Self {
        Self {
            panels: vec![initial],
            active: 0,
        }
    }

    fn from_ordered(panels: Vec<ViewPanelController>, active_id: PanelId) -> Option<Self> {
        if panels.is_empty()
            || panels.len() > MAXIMUM_VIEW_PANELS
            || panels
                .iter()
                .map(|panel| panel.id)
                .collect::<std::collections::HashSet<_>>()
                .len()
                != panels.len()
        {
            return None;
        }
        let active = panels.iter().position(|panel| panel.id == active_id)?;
        Some(Self { panels, active })
    }

    fn from_session(session: &SessionDocument, total_width: f32, content_top: f32) -> Result<Self> {
        let panel_width = f64::from((total_width / session.panels.len().max(1) as f32).max(1.0));
        let panels = session
            .panels
            .iter()
            .map(|saved| {
                let contig_length = saved
                    .locus
                    .end
                    .saturating_mul(2)
                    .max(saved.locus.end.saturating_add(1_000_000));
                let interval =
                    GenomicInterval::new(ContigId::new(0), saved.locus.start, saved.locus.end)?;
                let viewport = Viewport::new(interval, panel_width)?;
                let locus = format!(
                    "{}:{}-{}",
                    saved.locus.contig,
                    saved.locus.start.saturating_add(1),
                    saved.locus.end
                );
                let mut panel = ViewPanelController::new(
                    saved.id,
                    viewport,
                    Some(locus),
                    saved.locus.contig.clone(),
                    contig_length,
                );
                panel.vertical_scroll_points = saved.vertical_scroll_points;
                panel.content_bottom_points = content_top;
                Ok(panel)
            })
            .collect::<Result<Vec<_>>>()?;
        Self::from_ordered(panels, session.active_panel)
            .context("session active view panel is unavailable")
    }

    fn len(&self) -> usize {
        self.panels.len()
    }

    fn iter(&self) -> impl ExactSizeIterator<Item = &ViewPanelController> {
        self.panels.iter()
    }

    fn iter_mut(&mut self) -> impl ExactSizeIterator<Item = &mut ViewPanelController> {
        self.panels.iter_mut()
    }

    fn get(&self, id: PanelId) -> Option<&ViewPanelController> {
        self.panels.iter().find(|panel| panel.id == id)
    }

    fn get_mut(&mut self, id: PanelId) -> Option<&mut ViewPanelController> {
        self.panels.iter_mut().find(|panel| panel.id == id)
    }

    fn next_id(&self) -> PanelId {
        PanelId::new(
            self.panels
                .iter()
                .map(|panel| panel.id.get())
                .max()
                .unwrap_or_default()
                .saturating_add(1),
        )
    }

    fn push(&mut self, panel: ViewPanelController) -> bool {
        if self.panels.len() >= MAXIMUM_VIEW_PANELS || self.get(panel.id).is_some() {
            return false;
        }
        self.panels.push(panel);
        true
    }

    fn activate(&mut self, id: PanelId) -> bool {
        let Some(index) = self.panels.iter().position(|panel| panel.id == id) else {
            return false;
        };
        self.active = index;
        true
    }

    fn move_panel(&mut self, id: PanelId, new_index: usize) -> bool {
        let Some(old_index) = self.panels.iter().position(|panel| panel.id == id) else {
            return false;
        };
        let active_id = self.panels[self.active].id;
        let panel = self.panels.remove(old_index);
        self.panels.insert(new_index.min(self.panels.len()), panel);
        self.active = self
            .panels
            .iter()
            .position(|panel| panel.id == active_id)
            .expect("active panel survives a reorder");
        true
    }

    fn remove(&mut self, id: PanelId) -> Option<ViewPanelController> {
        if self.panels.len() == 1 {
            return None;
        }
        let index = self.panels.iter().position(|panel| panel.id == id)?;
        let removed_was_active = index == self.active;
        let panel = self.panels.remove(index);
        if removed_was_active {
            self.active = index.min(self.panels.len().saturating_sub(1));
        } else if index < self.active {
            self.active -= 1;
        }
        Some(panel)
    }
}

impl Deref for PanelWorkspace {
    type Target = ViewPanelController;

    fn deref(&self) -> &Self::Target {
        &self.panels[self.active]
    }
}

impl DerefMut for PanelWorkspace {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.panels[self.active]
    }
}

fn composite_panel_display_lists(panels: &PanelWorkspace) -> DisplayList {
    let mut composite = DisplayList::default();
    for panel in panels.iter() {
        if panel.id == panels.id {
            composite
                .rectangles
                .extend(panel.display_list.rectangles.iter().copied());
        } else {
            composite
                .rectangles
                .extend(
                    panel
                        .display_list
                        .rectangles
                        .iter()
                        .copied()
                        .map(|mut rectangle| {
                            // GPU hover and selection IDs are local to a panel.
                            // Inactive panels keep their semantic display lists for
                            // picking after activation, but cannot mirror an active
                            // panel's highlight accidentally.
                            rectangle.object_id = 0;
                            rectangle
                        }),
                );
        }
        composite
            .texts
            .extend(panel.display_list.texts.iter().cloned());
    }
    composite
}

fn alignment_frame_bottom(frame_top: f32, natural_bottom: f32, shared_height: Option<f32>) -> f32 {
    shared_height.map_or(natural_bottom, |height| {
        natural_bottom.max(frame_top + height)
    })
}

fn maximum_alignment_frame_height(panels: &PanelWorkspace, track_id: TrackId) -> Option<f32> {
    panels
        .iter()
        .filter_map(|panel| {
            panel
                .track_frames
                .iter()
                .find(|frame| frame.key == TrackFrameKey::Alignment(track_id))
                .map(|frame| (frame.bottom - frame.top).max(0.0))
        })
        .reduce(f32::max)
}

struct PrimaryAlignmentPanelState {
    panel_id: PanelId,
    query: Option<Arc<AlignmentQuery>>,
    query_stats: Option<QueryStats>,
}

fn synchronize_primary_alignment_panel_state(
    panels: &mut PanelWorkspace,
    states: Vec<PrimaryAlignmentPanelState>,
    cache_stats: Option<CacheStats>,
    remote_io_stats: Option<RemoteIoStats>,
) {
    for state in states {
        if let Some(panel) = panels.get_mut(state.panel_id) {
            panel.current_query = state.query;
            panel.available_modification_codes = panel
                .current_query
                .as_ref()
                .map_or_else(Vec::new, |query| collect_modification_codes(query));
            panel.query_stats = state.query_stats;
            panel.cache_stats = cache_stats;
            panel.remote_io_stats = remote_io_stats;
            panel.alignment_rows = None;
            panel.layout_stats = None;
        }
    }
}

impl ViewPanelController {
    fn new(
        id: PanelId,
        viewport: Viewport,
        requested_locus: Option<String>,
        contig_name: String,
        contig_length: u64,
    ) -> Self {
        let initial_interval = viewport.interval();
        Self {
            id,
            viewport,
            generation_clock: GenerationClock::default(),
            navigation_history: NavigationHistory::new(initial_interval),
            home_interval: initial_interval,
            requested_locus,
            contig_name,
            contig_length,
            selected_record: None,
            selected_alignment_track: None,
            selected_alignment_tracks: Vec::new(),
            selected_read_event: None,
            selected_pileup_position: None,
            selected_modification_position: None,
            selected_junction: None,
            selected_feature: None,
            selected_variant: None,
            selected_gwas: None,
            selected_quantitative: None,
            selected_copy_number: None,
            selected_mutation: None,
            selected_interaction: None,
            selected_chain: None,
            pending_read_selection: None,
            hovered_record: None,
            hover_inspector_target: None,
            display_list: DisplayList::default(),
            current_query: None,
            reference_slice: None,
            reference_settled_generation: None,
            alignment_rows: None,
            pending_queries: PendingQueries::default(),
            track_snapshots: Vec::new(),
            track_snapshot_interval: None,
            track_settled_generation: None,
            query_stats: None,
            layout_stats: None,
            cache_stats: None,
            remote_io_stats: None,
            available_modification_codes: Vec::new(),
            vertical_scroll_points: 0.0,
            content_bottom_points: 0.0,
            track_frames: Vec::new(),
            selected_track: None,
            last_gesture_query_at: None,
        }
    }

    fn request(&self) -> PanelGeneration {
        PanelGeneration::new(self.id, self.generation_clock.current())
    }

    fn owns(&self, request: PanelGeneration) -> bool {
        request.panel_id() == self.id
    }

    fn accepts(&self, request: PanelGeneration) -> bool {
        self.owns(request) && self.generation_clock.is_current(request.generation())
    }

    fn clear_selection(&mut self) {
        self.selected_record = None;
        self.selected_alignment_track = None;
        self.selected_alignment_tracks.clear();
        self.selected_read_event = None;
        self.selected_pileup_position = None;
        self.selected_modification_position = None;
        self.selected_junction = None;
        self.selected_feature = None;
        self.selected_variant = None;
        self.selected_gwas = None;
        self.selected_quantitative = None;
        self.selected_copy_number = None;
        self.selected_mutation = None;
        self.selected_interaction = None;
        self.selected_chain = None;
        self.pending_read_selection = None;
        self.hovered_record = None;
        self.hover_inspector_target = None;
    }
}

