const MAX_JUNCTION_ANNOTATION_RECORDS: usize = 200_000;
const MAX_JUNCTION_ANNOTATION_LABELS_PER_EVENT: usize = 8;

#[derive(Clone, Debug, Default)]
struct JunctionAnnotationContext {
    lookup: JunctionAnnotationLookup,
    labels: BTreeMap<(u64, u64), Vec<String>>,
    source_records_truncated: bool,
}

