fn snapshot_record_count(snapshot: &TrackSnapshot) -> usize {
    match &snapshot.data {
        TrackSnapshotData::Features(records) => records.len(),
        TrackSnapshotData::Variants(query) => query.records.len(),
        TrackSnapshotData::Quantitative(query) => query.records.len(),
        TrackSnapshotData::CopyNumber(query) => query.segments.len(),
        TrackSnapshotData::Mutations(query) => query.records.len(),
        TrackSnapshotData::Interactions(query) => query.records.len(),
        TrackSnapshotData::Gwas(query) => query.records.len(),
    }
}

fn quantitative_overlay_members<'a>(
    anchor: &'a TrackConfig,
    visible_tracks: &[&'a TrackConfig],
) -> Vec<&'a TrackConfig> {
    let Some(group) = anchor.quantitative.overlay_group else {
        return vec![anchor];
    };
    visible_tracks
        .iter()
        .copied()
        .filter(|track| {
            track.kind == TrackKind::Quantitative && track.quantitative.overlay_group == Some(group)
        })
        .collect()
}

fn quantitative_overlay_subtracks(
    members: &[&TrackConfig],
    top: f32,
    height: f32,
) -> Vec<TrackSubtrack> {
    if members.len() < 2 {
        return Vec::new();
    }
    let available_rows =
        (((height - 22.0).max(0.0) / 14.0).floor() as usize).clamp(1, MAX_OVERLAY_GUTTER_MEMBERS);
    let truncated = members.len() > available_rows;
    let member_rows = if truncated {
        available_rows.saturating_sub(1)
    } else {
        members.len()
    };
    let mut subtracks = members
        .iter()
        .take(member_rows)
        .enumerate()
        .map(|(index, member)| TrackSubtrack {
            label: member.name.clone(),
            detail: member
                .quantitative
                .overlay_group
                .map(|group| format!("overlay {group}")),
            top: top + 22.0 + index as f32 * 14.0,
            bottom: top + 36.0 + index as f32 * 14.0,
        })
        .collect::<Vec<_>>();
    if truncated {
        let omitted = members.len().saturating_sub(member_rows);
        let index = subtracks.len();
        subtracks.push(TrackSubtrack {
            label: format!("+{omitted} more tracks"),
            detail: Some("Open the Tracks menu to inspect every overlay member".to_owned()),
            top: top + 22.0 + index as f32 * 14.0,
            bottom: top + 36.0 + index as f32 * 14.0,
        });
    }
    subtracks
}

fn normalize_quantitative_overlay_settings(
    controls: &mut [(TrackId, QuantitativeTrackSettings)],
    edited_track: Option<TrackId>,
) {
    let edited_group_transform = edited_track.and_then(|edited_track| {
        controls
            .iter()
            .find(|(track_id, _)| *track_id == edited_track)
            .and_then(|(_, settings)| {
                settings
                    .overlay_group
                    .map(|group| (group, settings.scale_transform))
            })
    });
    for (_, settings) in controls {
        let Some(group) = settings.overlay_group else {
            continue;
        };
        settings.scale_mode = QuantitativeScaleMode::Shared;
        settings.scale_group = Some(group);
        if let Some((edited_group, transform)) = edited_group_transform
            && edited_group == group
        {
            settings.scale_transform = transform;
        }
    }
}

fn shared_copy_number_range(
    target: &TrackConfig,
    tracks: &[TrackConfig],
    snapshots: &[TrackSnapshot],
) -> Option<QuantitativeRange> {
    let target_query = snapshots
        .iter()
        .find(|snapshot| snapshot.id == target.id)
        .and_then(|snapshot| match &snapshot.data {
            TrackSnapshotData::CopyNumber(query) => Some(query.as_ref()),
            TrackSnapshotData::Features(_)
            | TrackSnapshotData::Variants(_)
            | TrackSnapshotData::Quantitative(_)
            | TrackSnapshotData::Mutations(_)
            | TrackSnapshotData::Interactions(_)
            | TrackSnapshotData::Gwas(_) => None,
        })?;
    let target_semantics = effective_copy_number_semantics(target, target_query);
    let baseline = match target_semantics {
        rgv_hts::CopyNumberValueSemantics::LogRatio => 0.0,
        rgv_hts::CopyNumberValueSemantics::Absolute => 2.0,
    };
    let mut minimum: f32 = baseline;
    let mut maximum: f32 = baseline;
    let mut found = false;
    for track in tracks.iter().filter(|track| {
        track.visible
            && track.kind == TrackKind::CopyNumber
            && track.quantitative.scale_mode == QuantitativeScaleMode::Shared
            && track.quantitative.scale_transform == target.quantitative.scale_transform
            && track.quantitative.scale_group == target.quantitative.scale_group
    }) {
        let Some(query) = snapshots
            .iter()
            .find(|snapshot| snapshot.id == track.id)
            .and_then(|snapshot| match &snapshot.data {
                TrackSnapshotData::CopyNumber(query) => Some(query.as_ref()),
                TrackSnapshotData::Features(_)
                | TrackSnapshotData::Variants(_)
                | TrackSnapshotData::Quantitative(_)
                | TrackSnapshotData::Mutations(_)
                | TrackSnapshotData::Interactions(_)
                | TrackSnapshotData::Gwas(_) => None,
            })
        else {
            continue;
        };
        if effective_copy_number_semantics(track, query) != target_semantics {
            continue;
        }
        for value in query
            .segments
            .iter()
            .map(|segment| segment.value)
            .filter(|value| value.is_finite())
        {
            minimum = minimum.min(value);
            maximum = maximum.max(value);
            found = true;
        }
    }
    found.then(|| {
        if minimum < maximum {
            QuantitativeRange { minimum, maximum }
        } else {
            let padding = minimum.abs().max(1.0) * 0.05;
            QuantitativeRange {
                minimum: minimum - padding,
                maximum: maximum + padding,
            }
        }
    })
}

fn effective_copy_number_semantics(
    track: &TrackConfig,
    query: &rgv_hts::CopyNumberQuery,
) -> rgv_hts::CopyNumberValueSemantics {
    match track.copy_number.value_mode {
        CopyNumberValueMode::Automatic => query.inferred_value_semantics,
        CopyNumberValueMode::LogRatio => rgv_hts::CopyNumberValueSemantics::LogRatio,
        CopyNumberValueMode::Absolute => rgv_hts::CopyNumberValueSemantics::Absolute,
    }
}

fn shared_quantitative_range(
    tracks: &[TrackConfig],
    snapshots: &[TrackSnapshot],
    viewport: Viewport,
    transform: QuantitativeScaleTransform,
    scale_group: Option<u32>,
) -> Option<QuantitativeRange> {
    tracks
        .iter()
        .filter(|track| {
            track.visible
                && track.kind == TrackKind::Quantitative
                && track.quantitative.scale_mode == QuantitativeScaleMode::Shared
                && track.quantitative.scale_transform == transform
                && track.quantitative.scale_group == scale_group
        })
        .filter_map(|track| {
            quantitative_display_records(track, snapshots, viewport).and_then(|records| {
                quantitative_data_range(&records, viewport, &track.quantitative)
            })
        })
        .reduce(QuantitativeRange::merge)
}

fn quantitative_track_y_at_position(
    track: &TrackConfig,
    tracks: &[TrackConfig],
    snapshots: &[TrackSnapshot],
    viewport: Viewport,
    position: u64,
    top: f32,
    height: f32,
) -> Option<f32> {
    let records = quantitative_display_records(track, snapshots, viewport)?;
    let value = quantitative_record_index_at_position(&records, position)
        .and_then(|index| records.get(index))?
        .value;
    let range = match track.quantitative.scale_mode {
        QuantitativeScaleMode::Automatic => {
            quantitative_data_range(&records, viewport, &track.quantitative)
        }
        QuantitativeScaleMode::Fixed => Some(QuantitativeRange {
            minimum: track.quantitative.fixed_minimum,
            maximum: track.quantitative.fixed_maximum,
        }),
        QuantitativeScaleMode::Shared => shared_quantitative_range(
            tracks,
            snapshots,
            viewport,
            track.quantitative.scale_transform,
            track.quantitative.scale_group,
        ),
    }
    .or_else(|| quantitative_data_range(&records, viewport, &track.quantitative))?;
    let transform = |value: f32| match track.quantitative.scale_transform {
        QuantitativeScaleTransform::Linear => value,
        QuantitativeScaleTransform::SignedLog10 => value.signum() * (1.0 + value.abs()).log10(),
    };
    let minimum = transform(range.minimum);
    let maximum = transform(range.maximum);
    let value = transform(value.clamp(range.minimum, range.maximum));
    Some(top + (maximum - value) / (maximum - minimum).max(f32::EPSILON) * height)
}

fn quantitative_display_records<'a>(
    track: &TrackConfig,
    snapshots: &'a [TrackSnapshot],
    viewport: Viewport,
) -> Option<Cow<'a, [rgv_hts::QuantitativeRecord]>> {
    let source = snapshots
        .iter()
        .find(|snapshot| snapshot.id == track.id)
        .and_then(|snapshot| match &snapshot.data {
            TrackSnapshotData::Quantitative(query) => Some(query.as_ref()),
            TrackSnapshotData::Features(_)
            | TrackSnapshotData::Variants(_)
            | TrackSnapshotData::CopyNumber(_)
            | TrackSnapshotData::Mutations(_)
            | TrackSnapshotData::Interactions(_)
            | TrackSnapshotData::Gwas(_) => None,
        })?;
    if track.quantitative.arithmetic == QuantitativeArithmetic::None {
        return Some(Cow::Borrowed(&source.records));
    }
    let operand_id = track.quantitative.operand_track?;
    let operand = snapshots
        .iter()
        .find(|snapshot| snapshot.id == operand_id)
        .and_then(|snapshot| match &snapshot.data {
            TrackSnapshotData::Quantitative(query) => Some(query.as_ref()),
            TrackSnapshotData::Features(_)
            | TrackSnapshotData::Variants(_)
            | TrackSnapshotData::CopyNumber(_)
            | TrackSnapshotData::Mutations(_)
            | TrackSnapshotData::Interactions(_)
            | TrackSnapshotData::Gwas(_) => None,
        })?;
    let interval = viewport.interval();
    Some(Cow::Owned(
        compose_quantitative_records(
            &source.records,
            &operand.records,
            track.quantitative.arithmetic,
            interval.start(),
            interval.end(),
            rgv_hts::MAX_QUANTITATIVE_RECORDS_PER_QUERY,
        )
        .records,
    ))
}

fn feature_record_index_at_position_and_row(
    records: &[rgv_hts::FeatureRecord],
    viewport: Viewport,
    position: u64,
    selected_row: usize,
    maximum_rows: usize,
    display_mode: FeatureDisplayMode,
) -> Option<usize> {
    let mut row_ends = vec![0_u64; maximum_rows.max(1)];
    records
        .iter()
        .enumerate()
        .filter_map(|(record_index, record)| {
            if record.end <= viewport.interval().start()
                || record.start >= viewport.interval().end()
            {
                return None;
            }
            let row = if display_mode == FeatureDisplayMode::Collapsed {
                0
            } else {
                row_ends.iter().position(|end| *end <= record.start)?
            };
            row_ends[row] = row_ends[row].max(record.end);
            (row == selected_row && record.start <= position && position < record.end)
                .then_some((record.end.saturating_sub(record.start), record_index))
        })
        .min()
        .map(|(_, record_index)| record_index)
}

fn quantitative_record_index_at_position(
    records: &[rgv_hts::QuantitativeRecord],
    position: u64,
) -> Option<usize> {
    records
        .iter()
        .enumerate()
        .filter(|(_, record)| record.start <= position && position < record.end)
        .min_by(|(_, left), (_, right)| {
            left.end
                .saturating_sub(left.start)
                .cmp(&right.end.saturating_sub(right.start))
                .then_with(|| left.start.cmp(&right.start))
        })
        .map(|(index, _)| index)
}

fn interaction_record_index_at_position(
    records: &[rgv_hts::InteractionRecord],
    contig: &str,
    position: u64,
    tolerance: u64,
) -> Option<usize> {
    records
        .iter()
        .enumerate()
        .filter_map(|(index, record)| {
            let endpoint_distance = [&record.source, &record.target]
                .into_iter()
                .filter(|endpoint| endpoint.contig == contig)
                .map(|endpoint| {
                    genomic_distance_to_interval(position, endpoint.start, endpoint.end)
                })
                .min();
            let (distance_class, distance) =
                if endpoint_distance.is_some_and(|value| value <= tolerance) {
                    (0_u8, endpoint_distance.unwrap_or_default())
                } else if record.source.contig == contig && record.target.contig == contig {
                    let source = record
                        .source
                        .start
                        .saturating_add(record.source.end.saturating_sub(record.source.start) / 2);
                    let target = record
                        .target
                        .start
                        .saturating_add(record.target.end.saturating_sub(record.target.start) / 2);
                    if position < source.min(target) || position > source.max(target) {
                        return None;
                    }
                    (1, 0)
                } else {
                    return None;
                };
            let span = record
                .source
                .start
                .min(record.target.start)
                .abs_diff(record.source.end.max(record.target.end));
            Some((
                index,
                distance_class,
                distance,
                span,
                record.score.unwrap_or_default(),
            ))
        })
        .min_by(|left, right| {
            left.1
                .cmp(&right.1)
                .then_with(|| left.2.cmp(&right.2))
                .then_with(|| left.3.cmp(&right.3))
                .then_with(|| right.4.total_cmp(&left.4))
                .then_with(|| left.0.cmp(&right.0))
        })
        .map(|(index, _, _, _, _)| index)
}

fn effective_template_length_bounds_for_filters(
    filters: &SessionFilters,
    query: &AlignmentQuery,
) -> TemplateLengthBounds {
    let inferred = query.pairs.inferred_bounds.unwrap_or_default();
    TemplateLengthBounds {
        minimum: filters.minimum_template_length.or(inferred.minimum),
        maximum: filters.maximum_template_length.or(inferred.maximum),
    }
}

fn alignment_sort_position(mode: AlignmentSortMode, viewport: Viewport) -> Option<u64> {
    if mode != AlignmentSortMode::Base {
        return None;
    }
    let interval = viewport.interval();
    Some(
        interval
            .start()
            .saturating_add(interval.len() / 2)
            .min(interval.end().saturating_sub(1)),
    )
}

fn mutation_record_index_at_position(
    records: &[rgv_hts::MutationRecord],
    sample_index: usize,
    position: u64,
) -> Option<usize> {
    records
        .iter()
        .enumerate()
        .filter(|(_, record)| {
            record.sample_index == sample_index && record.start <= position && position < record.end
        })
        .min_by_key(|(index, record)| (record.end.saturating_sub(record.start), *index))
        .map(|(index, _)| index)
}

fn genomic_distance_to_interval(position: u64, start: u64, end: u64) -> u64 {
    if position < start {
        start - position
    } else if position >= end {
        position.saturating_sub(end.saturating_sub(1))
    } else {
        0
    }
}

fn gwas_record_index_at_point(
    records: &[rgv_hts::GwasRecord],
    viewport: Viewport,
    local_x: f32,
    content_y: f32,
    top: f32,
    height: f32,
    settings: &GwasTrackSettings,
) -> Option<usize> {
    let tolerance = settings.point_size * 0.5 + 6.0;
    let tolerance_squared = tolerance * tolerance;
    records
        .iter()
        .enumerate()
        .filter_map(|(record_index, record)| {
            let point_x = viewport.pixel_at_genomic(record.position) as f32;
            let point_y = gwas_point_y(record.minus_log10_p, top, height, settings.maximum_score);
            let distance_squared = (local_x - point_x).powi(2) + (content_y - point_y).powi(2);
            (distance_squared <= tolerance_squared).then_some((distance_squared, record_index))
        })
        .min_by(|left, right| {
            left.0
                .total_cmp(&right.0)
                .then_with(|| left.1.cmp(&right.1))
        })
        .map(|(_, record_index)| record_index)
}

fn sashimi_track_detail(
    stats: &AlignmentLayoutStats,
    summary: &rgv_hts::JunctionSummary,
    scale_mode: SashimiScaleMode,
    fixed_maximum: u32,
    count_mode: SashimiCountMode,
) -> String {
    let mut detail = format!("{} shown", stats.rendered_junctions);
    if stats.hidden_junctions > 0 {
        let _ = write!(detail, " · {} filtered/capped", stats.hidden_junctions);
    }
    match count_mode {
        SashimiCountMode::Raw => {
            let _ = write!(detail, " · max {} reads", stats.maximum_junction_depth);
        }
        SashimiCountMode::CountsPerMillion if stats.junction_normalization_available => {
            let _ = write!(
                detail,
                " · max {:.1} CPM / {} mapped reads",
                stats.maximum_junction_value,
                summary
                    .provenance
                    .normalization_mapped_records
                    .unwrap_or_default()
            );
        }
        SashimiCountMode::CountsPerMillion => {
            let _ = write!(
                detail,
                " · CPM unavailable (index has no mapped-read total; raw fallback max {})",
                stats.maximum_junction_depth
            );
        }
    }
    let scale = match scale_mode {
        SashimiScaleMode::Automatic => "auto scale".to_owned(),
        SashimiScaleMode::Fixed => format!("fixed scale {fixed_maximum}"),
        SashimiScaleMode::Shared if stats.junction_normalization_available => {
            "shared visible-track scale".to_owned()
        }
        SashimiScaleMode::Shared => "shared scale unavailable; per-track fallback".to_owned(),
    };
    let _ = write!(detail, " · {scale}");
    detail
}

#[allow(clippy::too_many_arguments, clippy::too_many_lines)]
fn secondary_alignment_track_layout(
    panel_id: PanelId,
    track: &mut AlignmentTrackController,
    viewport: Viewport,
    contig_name: &str,
    frame_top: f32,
    selected_read_name_hash: Option<u64>,
    promoted_read_name_hash: Option<u64>,
    shared_sashimi_raw: Option<f64>,
    shared_sashimi_cpm: Option<f64>,
    junction_annotations: &JunctionAnnotationLookup,
) -> (Option<Arc<AlignmentLayout>>, TrackFrame) {
    let config = track.config.clone();
    let lifecycle = track.lifecycle.clone();
    let active_filters = track.active_filters.clone();
    let frame_height = config.height.clamp(40.0, 1_200.0);
    let frame_bottom = if config.collapsed {
        frame_top + 26.0
    } else {
        frame_top + frame_height
    };
    let source_label = Some(config.source.redacted_label());
    if config.collapsed {
        return (
            None,
            TrackFrame {
                key: TrackFrameKey::Alignment(config.id),
                name: config.name,
                kind: TrackKind::Alignment,
                source_label,
                top: frame_top,
                bottom: frame_bottom,
                visible: true,
                collapsed: true,
                frozen_bottom: None,
                subtracks: Vec::new(),
            },
        );
    }
    let expected_interval = track
        .dictionary
        .as_ref()
        .and_then(|dictionary| interval_for_track(dictionary, contig_name, viewport.interval()));
    let projection = track.projection_mut(panel_id);
    let Some(query) = projection.current_query.clone().filter(|query| {
        expected_interval.is_some_and(|interval| retained_data_overlaps(query.interval, interval))
    }) else {
        let status = if let Some(message) = &projection.unavailable {
            format!("Unavailable: {message}")
        } else {
            match &lifecycle {
                AlignmentTrackLifecycle::Opening => "Opening…".to_owned(),
                AlignmentTrackLifecycle::Ready => "Loading locus…".to_owned(),
                AlignmentTrackLifecycle::Failed(message) => format!("Error: {message}"),
            }
        };
        return (
            None,
            TrackFrame {
                key: TrackFrameKey::Alignment(config.id),
                name: config.name,
                kind: TrackKind::Alignment,
                source_label,
                top: frame_top,
                bottom: frame_bottom,
                visible: true,
                collapsed: false,
                frozen_bottom: None,
                subtracks: vec![TrackSubtrack {
                    label: status,
                    detail: None,
                    top: frame_top + 22.0,
                    bottom: frame_bottom,
                }],
            },
        );
    };

    let filters = &config.filters;
    let density = filters.alignment_density;
    let secondary_scale = density.sqrt();
    let content_top = frame_top + 22.0;
    let mut lane_top = content_top;
    let mut options = AlignmentLayoutOptions {
        show_reference: false,
        reference_top: lane_top,
        show_coverage: filters.show_coverage,
        coverage_top: lane_top,
        coverage_height: (48.0 * secondary_scale).clamp(28.0, 84.0),
        coverage_scale_maximum: filters.coverage_scale_maximum,
        ..AlignmentLayoutOptions::default()
    };
    if options.show_coverage {
        lane_top += options.coverage_height + 6.0;
    }
    let show_junctions = filters.show_junctions && !query.junctions.junctions.is_empty();
    options.show_junctions = show_junctions;
    options.junction_top = lane_top;
    options.junction_height = match filters.junction_display_mode {
        JunctionDisplayMode::Collapsed => (34.0 * secondary_scale).clamp(24.0, 58.0),
        JunctionDisplayMode::Expanded => (104.0 * secondary_scale).clamp(72.0, 180.0),
    };
    options.minimum_junction_depth = filters.minimum_junction_depth;
    options.junction_display_mode = filters.junction_display_mode;
    options.junction_count_mode = filters.sashimi_count_mode;
    options.show_junction_labels = filters.show_junction_labels;
    options.junction_annotation_fingerprint = junction_annotations.fingerprint();
    options.junction_scale_maximum = match filters.sashimi_scale_mode {
        SashimiScaleMode::Automatic => None,
        SashimiScaleMode::Fixed => Some(f64::from(filters.sashimi_fixed_scale_maximum)),
        SashimiScaleMode::Shared => match filters.sashimi_count_mode {
            SashimiCountMode::Raw => shared_sashimi_raw,
            SashimiCountMode::CountsPerMillion => shared_sashimi_cpm,
        },
    };
    if show_junctions {
        lane_top += options.junction_height + 6.0;
    }
    let show_modification_frequency =
        filters.show_modification_frequency && viewport.detail_level() != DetailLevel::Overview;
    options.show_modification_frequency = show_modification_frequency;
    options.modification_top = lane_top;
    options.modification_height = (26.0 * secondary_scale).clamp(20.0, 40.0);
    if show_modification_frequency {
        lane_top += options.modification_height + 8.0;
    }
    options.show_reads = filters.show_reads;
    options.reads_top = lane_top + if filters.show_reads { 1.0 } else { 0.0 };
    options.row_height = (7.0 * density).clamp(2.5, MAX_ALIGNMENT_ROW_HEIGHT);
    options.read_height = (5.0 * density).clamp(1.5, (options.row_height - 1.0).max(1.5));
    options.color_mode = filters.alignment_color_mode;
    options.group_mode = filters.alignment_group_mode;
    options.group_order = filters.alignment_group_order;
    options.sort_mode = filters.alignment_sort_mode;
    options.sort_order = filters.alignment_sort_order;
    options.sort_position = alignment_sort_position(filters.alignment_sort_mode, viewport);
    options.promoted_read_name_hash = promoted_read_name_hash;
    options.selected_chain_read_name_hash = selected_read_name_hash.or(promoted_read_name_hash);
    options.view_as_pairs = filters.view_as_pairs;
    options.pair_length_bounds = effective_template_length_bounds_for_filters(filters, &query);
    options.minimum_allele_fraction = filters.minimum_allele_fraction;
    options.quality_weighted_alleles = filters.quality_weighted_alleles;
    options.show_coverage_center_line = filters.show_coverage_center_line;
    options.read_base_display_mode = filters.read_base_display_mode;
    options.shade_read_bases_by_quality = filters.shade_read_bases_by_quality;
    options.minimum_indel_size = filters.minimum_indel_size;
    options.minimum_event_label_size = filters.minimum_event_label_size;
    options.show_modified_bases = filters.show_modified_bases;
    options.minimum_modification_probability = filters.minimum_modification_probability;
    options.modified_base_color_mode = filters.modified_base_color_mode;
    for (slot, code) in options.hidden_modification_codes.iter_mut().zip(
        filters
            .hidden_modification_codes
            .iter()
            .filter_map(|value| parse_modification_code(value)),
    ) {
        *slot = Some(code);
    }
    let available_read_height = (frame_bottom - options.reads_top - 6.0).max(options.row_height);
    options.max_rows = if options.show_reads {
        (available_read_height / options.row_height)
            .floor()
            .clamp(1.0, 4_096.0) as usize
    } else {
        1
    };

    let rows_match = projection.alignment_rows.as_ref().is_some_and(|cached| {
        Arc::ptr_eq(&cached.query, &query)
            && cached.group_mode == options.group_mode
            && cached.group_order == options.group_order
            && cached.sort_mode == options.sort_mode
            && cached.sort_order == options.sort_order
            && cached.sort_position == options.sort_position
            && cached.promoted_read_name_hash == options.promoted_read_name_hash
            && cached.max_rows == options.max_rows
            && cached.view_as_pairs == options.view_as_pairs
            && cached.pair_length_bounds == options.pair_length_bounds
    });
    if !rows_match {
        let previous = projection.alignment_rows.as_ref().and_then(|cached| {
            (cached.group_mode == options.group_mode
                && cached.group_order == options.group_order
                && cached.sort_mode == options.sort_mode
                && cached.sort_order == options.sort_order
                && cached.sort_position == options.sort_position
                && cached.promoted_read_name_hash == options.promoted_read_name_hash
                && cached.max_rows == options.max_rows
                && cached.view_as_pairs == options.view_as_pairs
                && cached.pair_length_bounds == options.pair_length_bounds)
                .then_some(cached.layout.as_ref())
        });
        let layout = Arc::new(assign_alignment_rows(&query, options, previous));
        projection.alignment_rows = Some(CachedAlignmentRows {
            query: Arc::clone(&query),
            layout,
            group_mode: options.group_mode,
            group_order: options.group_order,
            sort_mode: options.sort_mode,
            sort_order: options.sort_order,
            sort_position: options.sort_position,
            promoted_read_name_hash: options.promoted_read_name_hash,
            max_rows: options.max_rows,
            view_as_pairs: options.view_as_pairs,
            pair_length_bounds: options.pair_length_bounds,
        });
        projection.cached_layout = None;
    }
    let key = alignment_layout_key(
        PanelTrackId::new(panel_id, config.id),
        Some(&config.source),
        viewport,
        query.interval,
        &active_filters,
        &options,
        frame_top,
    );
    let layout = if let Some((_, layout)) = projection
        .cached_layout
        .as_ref()
        .filter(|(cached_key, _)| *cached_key == key)
    {
        Arc::clone(layout)
    } else {
        let rows = projection
            .alignment_rows
            .as_ref()
            .expect("secondary alignment rows exist for a loaded query");
        let layout = Arc::new(layout_alignment_query_with_rows_and_annotations(
            &query,
            viewport,
            options,
            &rows.layout,
            Some(junction_annotations),
        ));
        projection.cached_layout = Some((key, Arc::clone(&layout)));
        layout
    };
    let mut subtracks = Vec::with_capacity(4);
    if options.show_coverage {
        subtracks.push(TrackSubtrack {
            label: "Coverage".to_owned(),
            detail: Some(filters.coverage_scale_maximum.map_or_else(
                || format!("auto {}×", layout.stats.maximum_coverage),
                |maximum| format!("max {}× · fixed {maximum}×", layout.stats.maximum_coverage),
            )),
            top: options.coverage_top,
            bottom: options.coverage_top + options.coverage_height,
        });
    }
    if show_junctions {
        subtracks.push(TrackSubtrack {
            label: "Sashimi".to_owned(),
            detail: Some(sashimi_track_detail(
                &layout.stats,
                &query.junctions,
                filters.sashimi_scale_mode,
                filters.sashimi_fixed_scale_maximum,
                filters.sashimi_count_mode,
            )),
            top: options.junction_top,
            bottom: options.junction_top + options.junction_height,
        });
    }
    if show_modification_frequency {
        subtracks.push(TrackSubtrack {
            label: "Modifications".to_owned(),
            detail: Some(format!("{} types", query.pileup.modifications.series.len())),
            top: options.modification_top,
            bottom: options.modification_top + options.modification_height,
        });
    }
    if options.show_reads {
        let mut read_details = Vec::new();
        if query.stats.truncated {
            read_details.push(format!(
                "sampled {}/{}",
                query.stats.records_emitted, query.stats.records_eligible
            ));
        }
        if layout.stats.bisulfite_marks_omitted > 0 {
            read_details.push(format!(
                "{} bisulfite marks omitted at display cap",
                layout.stats.bisulfite_marks_omitted
            ));
        }
        if layout.stats.smrt_kinetics_marks_omitted > 0 {
            read_details.push(format!(
                "{} PacBio kinetic marks omitted at display cap",
                layout.stats.smrt_kinetics_marks_omitted
            ));
        }
        if layout.stats.ultima_quality_marks_omitted > 0 {
            read_details.push(format!(
                "{} Ultima quality marks omitted at display cap",
                layout.stats.ultima_quality_marks_omitted
            ));
        }
        if layout.stats.sbx_tail_marks_omitted > 0 {
            read_details.push(format!(
                "{} SBX simplex-tail marks omitted at display cap",
                layout.stats.sbx_tail_marks_omitted
            ));
        }
        if matches!(
            filters.alignment_color_mode,
            AlignmentColorMode::SmrtKinetics(_)
        ) {
            if layout.stats.smrt_kinetics_unavailable_records > 0 {
                read_details.push(format!(
                    "{} reads missing the selected PacBio kinetic array or sequence",
                    layout.stats.smrt_kinetics_unavailable_records
                ));
            }
            if layout.stats.smrt_kinetics_malformed_records > 0 {
                read_details.push(format!(
                    "{} malformed PacBio kinetic arrays",
                    layout.stats.smrt_kinetics_malformed_records
                ));
            }
        }
        if matches!(filters.alignment_color_mode, AlignmentColorMode::Ultima(_)) {
            if layout.stats.ultima_unavailable_records > 0 {
                read_details.push(format!(
                    "{} reads missing Ultima sequence, qualities, or tp",
                    layout.stats.ultima_unavailable_records
                ));
            }
            if layout.stats.ultima_malformed_records > 0 {
                read_details.push(format!(
                    "{} reads with malformed Ultima evidence",
                    layout.stats.ultima_malformed_records
                ));
            }
            if layout.stats.ultima_unavailable_events > 0 {
                read_details.push(format!(
                    "{} indels shown without Ultima quality evidence",
                    layout.stats.ultima_unavailable_events
                ));
            }
        }
        if matches!(filters.alignment_color_mode, AlignmentColorMode::Sbx(_)) {
            if layout.stats.sbx_unavailable_records > 0 {
                read_details.push(format!(
                    "{} reads missing usable SBX sequence/qualities",
                    layout.stats.sbx_unavailable_records
                ));
            }
            if layout.stats.sbx_unavailable_insertions > 0 {
                read_details.push(format!(
                    "{} SBX insertions shown without quality classification",
                    layout.stats.sbx_unavailable_insertions
                ));
            }
        }
        if matches!(
            filters.alignment_color_mode,
            AlignmentColorMode::Bisulfite(_)
        ) && query.reference.is_none()
        {
            read_details.push(
                "bisulfite conversion unavailable: load a matching reference FASTA".to_owned(),
            );
        }
        subtracks.push(TrackSubtrack {
            label: "Reads".to_owned(),
            detail: (!read_details.is_empty()).then(|| read_details.join(" · ")),
            top: options.reads_top,
            bottom: frame_bottom,
        });
    }
    (
        Some(layout),
        TrackFrame {
            key: TrackFrameKey::Alignment(config.id),
            name: config.name,
            kind: TrackKind::Alignment,
            source_label,
            top: frame_top,
            bottom: frame_bottom,
            visible: true,
            collapsed: false,
            frozen_bottom: None,
            subtracks,
        },
    )
}

#[allow(clippy::too_many_lines)]
fn alignment_layout_key(
    owner: PanelTrackId,
    source: Option<&TrackSource>,
    viewport: Viewport,
    query_interval: GenomicInterval,
    filters: &ActiveFilters,
    options: &AlignmentLayoutOptions,
    track_height: f32,
) -> LayoutTileKey {
    let source_value = source.map_or(0, |source| match source {
        TrackSource::Local { path } => fnv64(path.as_bytes()),
        TrackSource::Remote { url } => fnv64(url.as_bytes()),
    });
    let mut layout_bytes = Vec::with_capacity(128);
    layout_bytes.extend_from_slice(&viewport.pixel_width().to_bits().to_le_bytes());
    layout_bytes.extend_from_slice(&viewport.exact_start().to_bits().to_le_bytes());
    layout_bytes.extend_from_slice(&viewport.span().to_bits().to_le_bytes());
    layout_bytes.extend_from_slice(&query_interval.contig().get().to_le_bytes());
    layout_bytes.extend_from_slice(&query_interval.start().to_le_bytes());
    layout_bytes.extend_from_slice(&query_interval.end().to_le_bytes());
    for value in [
        options.reference_top,
        options.coverage_top,
        options.coverage_height,
        options.junction_top,
        options.junction_height,
        options.reads_top,
        options.row_height,
        options.read_height,
        track_height,
    ] {
        layout_bytes.extend_from_slice(&value.to_bits().to_le_bytes());
    }
    layout_bytes.extend_from_slice(&options.max_rows.to_le_bytes());
    layout_bytes.push(options.group_order as u8);
    layout_bytes.push(options.sort_order as u8);
    layout_bytes.extend_from_slice(&options.sort_position.unwrap_or(u64::MAX).to_le_bytes());
    layout_bytes.push(u8::from(options.view_as_pairs));
    layout_bytes.extend_from_slice(
        &options
            .pair_length_bounds
            .minimum
            .unwrap_or(u64::MAX)
            .to_le_bytes(),
    );
    layout_bytes.extend_from_slice(
        &options
            .pair_length_bounds
            .maximum
            .unwrap_or(u64::MAX)
            .to_le_bytes(),
    );
    layout_bytes.extend_from_slice(&options.minimum_allele_fraction.to_bits().to_le_bytes());
    layout_bytes.push(u8::from(options.quality_weighted_alleles));
    layout_bytes.push(u8::from(options.show_reference));
    layout_bytes.push(u8::from(options.show_coverage));
    layout_bytes.push(u8::from(options.show_junctions));
    layout_bytes.push(u8::from(options.show_reads));
    layout_bytes.extend_from_slice(&options.minimum_junction_depth.to_le_bytes());
    layout_bytes.push(options.junction_display_mode as u8);
    layout_bytes.extend_from_slice(
        &options
            .junction_scale_maximum
            .unwrap_or(f64::NAN)
            .to_bits()
            .to_le_bytes(),
    );
    layout_bytes.push(options.junction_count_mode as u8);
    layout_bytes.push(u8::from(options.show_junction_labels));
    layout_bytes.extend_from_slice(&options.junction_annotation_fingerprint.to_le_bytes());
    layout_bytes.extend_from_slice(&options.selected_junction[0].to_le_bytes());
    layout_bytes.extend_from_slice(&options.selected_junction[1].to_le_bytes());
    layout_bytes.extend_from_slice(
        &options
            .coverage_scale_maximum
            .unwrap_or(u32::MAX)
            .to_le_bytes(),
    );
    layout_bytes.push(u8::from(options.show_coverage_center_line));
    layout_bytes.push(options.read_base_display_mode as u8);
    layout_bytes.push(u8::from(options.shade_read_bases_by_quality));
    layout_bytes.extend_from_slice(&options.minimum_indel_size.to_le_bytes());
    layout_bytes.extend_from_slice(&options.minimum_event_label_size.to_le_bytes());
    layout_bytes.push(u8::from(options.show_modified_bases));
    layout_bytes.push(u8::from(options.show_modification_frequency));
    layout_bytes.extend_from_slice(&options.modification_top.to_bits().to_le_bytes());
    layout_bytes.extend_from_slice(&options.modification_height.to_bits().to_le_bytes());
    layout_bytes.extend_from_slice(
        &options
            .selected_modification_position
            .unwrap_or(u64::MAX)
            .to_le_bytes(),
    );
    layout_bytes.extend_from_slice(
        &options
            .selected_chain_read_name_hash
            .unwrap_or(u64::MAX)
            .to_le_bytes(),
    );
    layout_bytes.extend_from_slice(
        &options
            .promoted_read_name_hash
            .unwrap_or(u64::MAX)
            .to_le_bytes(),
    );
    layout_bytes.push(options.minimum_modification_probability);
    layout_bytes.push(options.modified_base_color_mode as u8);
    for code in options.hidden_modification_codes {
        match code {
            None => layout_bytes.push(0),
            Some(ModificationCode::Letter(letter)) => {
                layout_bytes.push(1);
                layout_bytes.push(letter);
            }
            Some(ModificationCode::Chebi(code)) => {
                layout_bytes.push(2);
                layout_bytes.extend_from_slice(&code.to_le_bytes());
            }
        }
    }
    layout_bytes.extend_from_slice(
        &options
            .selected_pileup_position
            .unwrap_or(u64::MAX)
            .to_le_bytes(),
    );
    let style_version = alignment_color_mode_fingerprint(options.color_mode)
        | alignment_group_mode_fingerprint(options.group_mode) << 24
        | alignment_sort_mode_fingerprint(options.sort_mode) << 48;
    LayoutTileKey {
        owner,
        source: SourceFingerprint::new(source_value),
        interval: viewport.interval(),
        detail: viewport.detail_level(),
        filter_hash: filters.alignment.fingerprint()
            ^ u64::from(filters.include_secondary)
            ^ (u64::from(filters.include_supplementary) << 1),
        layout_hash: fnv64(&layout_bytes),
        style_version,
    }
}

const fn alignment_color_mode_fingerprint(mode: AlignmentColorMode) -> u64 {
    match mode {
        AlignmentColorMode::None => 0,
        AlignmentColorMode::Strand => 1,
        AlignmentColorMode::MappingQuality => 2,
        AlignmentColorMode::ReadGroup => 3,
        AlignmentColorMode::Haplotype => 4,
        AlignmentColorMode::TemplateLength => 5,
        AlignmentColorMode::PairOrientation => 6,
        AlignmentColorMode::UnexpectedPair => 7,
        AlignmentColorMode::MateContig => 8,
        AlignmentColorMode::FirstOfPairStrand => 9,
        AlignmentColorMode::Bisulfite(context) => 10 + bisulfite_context_fingerprint(context),
        AlignmentColorMode::SmrtKinetics(mode) => 16 + smrt_kinetics_mode_fingerprint(mode),
        AlignmentColorMode::Ultima(options) => {
            let maximum = match options.maximum_homopolymer_length_override {
                Some(value) => value as u64,
                None => 0,
            };
            23 | (options.quality_mode as u64) << 8
                | maximum << 16
                | (options.maximum_homopolymer_length_override.is_some() as u64) << 40
        }
        AlignmentColorMode::Sbx(options) => {
            22 | (options.simplex_tail_mode as u64) << 8
                | (options.discordant_quality_maximum as u64) << 16
                | (options.simplex_tail_quality_maximum as u64) << 24
        }
        AlignmentColorMode::Tag(tag) => 32 | ((tag[0] as u64) << 8) | ((tag[1] as u64) << 16),
    }
}

const fn smrt_kinetics_mode_fingerprint(mode: SmrtKineticsMode) -> u64 {
    match mode {
        SmrtKineticsMode::SubreadIpd => 0,
        SmrtKineticsMode::SubreadPulseWidth => 1,
        SmrtKineticsMode::CcsForwardIpd => 2,
        SmrtKineticsMode::CcsForwardPulseWidth => 3,
        SmrtKineticsMode::CcsReverseIpd => 4,
        SmrtKineticsMode::CcsReversePulseWidth => 5,
    }
}

const fn bisulfite_context_fingerprint(context: BisulfiteContext) -> u64 {
    match context {
        BisulfiteContext::Cg => 0,
        BisulfiteContext::Chg => 1,
        BisulfiteContext::Chh => 2,
        BisulfiteContext::Hcg => 3,
        BisulfiteContext::Gch => 4,
        BisulfiteContext::Wcg => 5,
    }
}

const fn alignment_group_mode_fingerprint(mode: AlignmentGroupMode) -> u64 {
    match mode {
        AlignmentGroupMode::None => 0,
        AlignmentGroupMode::Strand => 1,
        AlignmentGroupMode::ReadGroup => 2,
        AlignmentGroupMode::Haplotype => 3,
        AlignmentGroupMode::Chimeric => 4,
        AlignmentGroupMode::Supplementary => 5,
        AlignmentGroupMode::LeftClip => 6,
        AlignmentGroupMode::RightClip => 7,
        AlignmentGroupMode::PairOrientation => 8,
        AlignmentGroupMode::UnexpectedPair => 9,
        AlignmentGroupMode::MateContig => 10,
        AlignmentGroupMode::ReadOrder => 11,
        AlignmentGroupMode::FirstOfPairStrand => 12,
        AlignmentGroupMode::Tag(tag) => 13 | ((tag[0] as u64) << 8) | ((tag[1] as u64) << 16),
    }
}

const fn alignment_sort_mode_fingerprint(mode: AlignmentSortMode) -> u64 {
    match mode {
        AlignmentSortMode::Start => 0,
        AlignmentSortMode::Strand => 1,
        AlignmentSortMode::FirstOfPairStrand => 2,
        AlignmentSortMode::MappingQuality => 3,
        AlignmentSortMode::ReadName => 4,
        AlignmentSortMode::ReadGroup => 5,
        AlignmentSortMode::Haplotype => 6,
        AlignmentSortMode::AlignedLength => 7,
        AlignmentSortMode::LeftClip => 8,
        AlignmentSortMode::RightClip => 9,
        AlignmentSortMode::TemplateLength => 10,
        AlignmentSortMode::PairOrientation => 11,
        AlignmentSortMode::MateContig => 12,
        AlignmentSortMode::PairStatus => 13,
        AlignmentSortMode::ReadOrder => 14,
        AlignmentSortMode::Base => 15,
        AlignmentSortMode::Tag(tag) => 16 | ((tag[0] as u64) << 8) | ((tag[1] as u64) << 16),
    }
}

fn parse_style_tag(value: &str) -> Option<[u8; 2]> {
    let bytes: [u8; 2] = value.as_bytes().try_into().ok()?;
    (bytes[0].is_ascii_alphabetic() && bytes[1].is_ascii_alphanumeric()).then_some(bytes)
}

fn persisted_style_tag(
    color: AlignmentColorMode,
    group: AlignmentGroupMode,
    sort: AlignmentSortMode,
) -> String {
    let tag = match (color, group, sort) {
        (AlignmentColorMode::Tag(tag), _, _)
        | (_, AlignmentGroupMode::Tag(tag), _)
        | (_, _, AlignmentSortMode::Tag(tag)) => tag,
        _ => *b"NM",
    };
    String::from_utf8_lossy(&tag).into_owned()
}

fn wheel_primary_axis(delta: MouseScrollDelta) -> f32 {
    match delta {
        MouseScrollDelta::LineDelta(x, y) => {
            let axis = if y.abs() > f32::EPSILON { y } else { x };
            axis * 40.0
        }
        MouseScrollDelta::PixelDelta(position) => {
            let x = position.x as f32;
            let y = position.y as f32;
            if y.abs() > f32::EPSILON { y } else { x }
        }
    }
}

fn overview_drag_step(
    viewport: Viewport,
    anchor_fraction: f64,
    horizontal_drag_pixels: f64,
    vertical_drag_pixels: f64,
    contig_length: u64,
) -> Option<Viewport> {
    let zoom_factor = (-vertical_drag_pixels * 0.012).exp();
    let zoomed = viewport
        .zoom_at(
            viewport.pixel_width() * anchor_fraction.clamp(0.0, 1.0),
            zoom_factor,
            contig_length,
        )
        .ok()?;
    let pan_gain = overview_pan_gain(zoomed.span(), contig_length);
    zoomed
        .pan_pixels(horizontal_drag_pixels * pan_gain, contig_length)
        .ok()
}

fn overview_drag_origin(
    viewport: Viewport,
    pointer_position: u64,
    handle_fraction: Option<f64>,
    contig_length: u64,
) -> (Viewport, f64) {
    if let Some(fraction) = handle_fraction {
        return (viewport, fraction.clamp(0.0, 1.0));
    }
    let interval = viewport.interval();
    if interval.contains(pointer_position) {
        return (
            viewport,
            ((pointer_position as f64 - viewport.exact_start()) / viewport.span()).clamp(0.0, 1.0),
        );
    }
    viewport
        .centered_on(pointer_position, contig_length)
        .map_or((viewport, 0.5), |centered| (centered, 0.5))
}

fn retained_data_overlaps(loaded: GenomicInterval, viewport: GenomicInterval) -> bool {
    loaded.overlaps(viewport)
}

fn extend_alignment_layers(
    pinned: &mut DisplayList,
    scrollable: &mut DisplayList,
    layout: &AlignmentLayout,
) {
    debug_assert!(layout.pinned_rectangle_count <= layout.display_list.rectangles.len());
    debug_assert!(layout.pinned_text_count <= layout.display_list.texts.len());
    let rectangle_boundary = layout
        .pinned_rectangle_count
        .min(layout.display_list.rectangles.len());
    let text_boundary = layout
        .pinned_text_count
        .min(layout.display_list.texts.len());
    pinned.rectangles.extend(
        layout.display_list.rectangles[..rectangle_boundary]
            .iter()
            .copied(),
    );
    pinned
        .texts
        .extend(layout.display_list.texts[..text_boundary].iter().cloned());
    scrollable.rectangles.extend(
        layout.display_list.rectangles[rectangle_boundary..]
            .iter()
            .copied(),
    );
    scrollable
        .texts
        .extend(layout.display_list.texts[text_boundary..].iter().cloned());
}

fn fill_lone_alignment_track(
    frames: &mut [TrackFrame],
    content_bottom: f32,
    viewport_bottom: f32,
) -> f32 {
    if frames.len() != 1
        || !matches!(frames[0].key, TrackFrameKey::Alignment(_))
        || content_bottom >= viewport_bottom
    {
        return content_bottom;
    }
    let frame = &mut frames[0];
    frame.bottom = viewport_bottom;
    if let Some(reads) = frame.subtracks.last_mut() {
        reads.bottom = viewport_bottom;
    }
    viewport_bottom
}

fn overview_pan_gain(span: f64, contig_length: u64) -> f64 {
    let visible_fraction = span / contig_length.max(1) as f64;
    2.5 + 5.5 * visible_fraction.clamp(0.0, 1.0).sqrt()
}

fn density_from_horizontal_drag(origin: f32, drag_pixels: f32) -> f32 {
    (origin * (drag_pixels * 0.012).exp()).clamp(MIN_VERTICAL_DENSITY, MAX_VERTICAL_DENSITY)
}

fn vertical_overview_step(
    density: f32,
    scroll: f32,
    anchor_y: f32,
    horizontal_drag_pixels: f32,
    vertical_drag_pixels: f32,
) -> (f32, f32) {
    let density = density.clamp(MIN_VERTICAL_DENSITY, MAX_VERTICAL_DENSITY);
    let next_density = density_from_horizontal_drag(density, horizontal_drag_pixels);
    let density_ratio = next_density / density.max(f32::EPSILON);
    let anchored_scroll = (scroll + anchor_y) * density_ratio - anchor_y;
    let next_scroll =
        anchored_scroll + vertical_drag_pixels * vertical_overview_pan_gain(next_density);
    (next_density, next_scroll.max(0.0))
}

fn vertical_overview_pan_gain(density: f32) -> f32 {
    let compact_fraction = ((MAX_VERTICAL_DENSITY
        - density.clamp(MIN_VERTICAL_DENSITY, MAX_VERTICAL_DENSITY))
        / (MAX_VERTICAL_DENSITY - MIN_VERTICAL_DENSITY))
        .clamp(0.0, 1.0);
    2.0 + 6.0 * compact_fraction.sqrt()
}

fn auxiliary_track_scale(density: f32) -> f32 {
    let density = density.clamp(MIN_VERTICAL_DENSITY, MAX_VERTICAL_DENSITY);
    if density <= 1.0 {
        density
    } else {
        density.sqrt()
    }
}

fn alignment_record_index(object_id: u32) -> Option<usize> {
    let record_id = record_object_id(object_id);
    (record_id > 0 && record_id < 1_000_000)
        .then(|| usize::try_from(record_id - 1).ok())
        .flatten()
}

fn alignment_track_at_content_y(frames: &[TrackFrame], content_y: f32) -> Option<TrackId> {
    frames.iter().find_map(|frame| {
        (content_y >= frame.top && content_y < frame.bottom)
            .then_some(frame.key)
            .and_then(|key| match key {
                TrackFrameKey::Alignment(id) => Some(id),
                TrackFrameKey::Reference | TrackFrameKey::Auxiliary(_) => None,
            })
    })
}

fn alignment_lane_at_screen_y(
    frames: &[TrackFrame],
    label: &str,
    screen_y: f32,
    vertical_scroll: f32,
) -> Option<TrackId> {
    frames.iter().find_map(|frame| {
        let TrackFrameKey::Alignment(id) = frame.key else {
            return None;
        };
        frame.subtracks.iter().find_map(|subtrack| {
            if subtrack.label != label {
                return None;
            }
            let y = if frame
                .frozen_bottom
                .is_some_and(|frozen_bottom| subtrack.bottom <= frozen_bottom)
            {
                screen_y
            } else {
                screen_y + vertical_scroll
            };
            (y >= subtrack.top && y < subtrack.bottom).then_some(id)
        })
    })
}

fn alignment_record_at_point(display: &DisplayList, x: f32, y: f32) -> Option<usize> {
    display
        .rectangles
        .iter()
        .rev()
        .find(|rectangle| {
            alignment_record_index(rectangle.object_id).is_some()
                && x >= rectangle.x
                && x <= rectangle.x + rectangle.width
                && y >= rectangle.y
                && y <= rectangle.y + rectangle.height
        })
        .and_then(|rectangle| alignment_record_index(rectangle.object_id))
}

fn find_read_event(record: &AlignmentRecord, position: f64, tolerance: f64) -> Option<usize> {
    let mut reference_position = record.start;
    let mut best = None::<(f64, usize)>;
    for (index, operation) in record.cigar.iter().enumerate() {
        let length = u64::from(operation.len);
        match operation.kind {
            CigarOpKind::Match | CigarOpKind::SequenceMatch | CigarOpKind::SequenceMismatch => {
                reference_position = reference_position.saturating_add(length);
            }
            CigarOpKind::Deletion | CigarOpKind::ReferenceSkip => {
                let end = reference_position.saturating_add(length);
                if position >= reference_position as f64 && position < end as f64 {
                    return Some(index);
                }
                reference_position = end;
            }
            CigarOpKind::Insertion
            | CigarOpKind::SoftClip
            | CigarOpKind::HardClip
            | CigarOpKind::Padding => {
                let distance = (position - reference_position as f64).abs();
                if distance <= tolerance
                    && best.is_none_or(|(best_distance, _)| distance < best_distance)
                {
                    best = Some((distance, index));
                }
            }
        }
    }
    best.map(|(_, index)| index)
}

struct ReadEventDetails {
    fields: Vec<(String, String)>,
    copy_sequence: Option<String>,
}

#[allow(clippy::too_many_lines)]
fn read_event_details(
    record: &AlignmentRecord,
    operation_index: usize,
    contig_name: &str,
) -> Option<ReadEventDetails> {
    let operation = *record.cigar.get(operation_index)?;
    let mut reference_position = record.start;
    let mut read_position = 0_usize;
    for preceding in &record.cigar[..operation_index] {
        match preceding.kind {
            CigarOpKind::Match | CigarOpKind::SequenceMatch | CigarOpKind::SequenceMismatch => {
                reference_position = reference_position.saturating_add(u64::from(preceding.len));
                read_position = read_position.saturating_add(preceding.len as usize);
            }
            CigarOpKind::Deletion | CigarOpKind::ReferenceSkip => {
                reference_position = reference_position.saturating_add(u64::from(preceding.len));
            }
            CigarOpKind::Insertion | CigarOpKind::SoftClip => {
                read_position = read_position.saturating_add(preceding.len as usize);
            }
            CigarOpKind::HardClip | CigarOpKind::Padding => {}
        }
    }

    let kind = match operation.kind {
        CigarOpKind::Insertion => "Insertion",
        CigarOpKind::Deletion => "Deletion",
        CigarOpKind::ReferenceSkip => "Reference skip",
        CigarOpKind::SoftClip => "Soft clip",
        CigarOpKind::HardClip => "Hard clip",
        CigarOpKind::Padding => "Padding",
        CigarOpKind::Match | CigarOpKind::SequenceMatch | CigarOpKind::SequenceMismatch => {
            return None;
        }
    };
    let reference_label = match operation.kind {
        CigarOpKind::Deletion | CigarOpKind::ReferenceSkip => format!(
            "{contig_name}:{}-{}",
            reference_position + 1,
            reference_position.saturating_add(u64::from(operation.len))
        ),
        _ => format!(
            "{contig_name}:{}|{}",
            reference_position,
            reference_position.saturating_add(1)
        ),
    };
    let mut fields = vec![
        ("Selected event".to_owned(), kind.to_owned()),
        ("Event length".to_owned(), format!("{} bp", operation.len)),
        ("Event locus".to_owned(), reference_label),
    ];
    let event_read_range = matches!(
        operation.kind,
        CigarOpKind::Insertion | CigarOpKind::SoftClip
    )
    .then(|| {
        let end = read_position.saturating_add(operation.len as usize);
        read_position..end
    });
    let mut copy_sequence = None;
    if let Some(range) = event_read_range {
        fields.push((
            "Read positions".to_owned(),
            format!("{}-{}", range.start + 1, range.end),
        ));
        match &record.sequence {
            SequenceData::Present { bases, qualities } => {
                let (sequence, event_qualities) = oriented_event_sequence(
                    bases,
                    qualities.as_deref(),
                    range,
                    record.flags.is_reverse(),
                );
                fields.push((
                    "Sequence preview".to_owned(),
                    bounded_sequence_preview(&sequence),
                ));
                if let Some(event_qualities) = event_qualities {
                    let mean = (!event_qualities.is_empty()).then(|| {
                        event_qualities
                            .iter()
                            .map(|value| u64::from(*value))
                            .sum::<u64>() as f64
                            / event_qualities.len() as f64
                    });
                    fields.push((
                        "Event qualities".to_owned(),
                        mean.map_or_else(
                            || "unavailable".to_owned(),
                            |mean| format!("mean {mean:.1}"),
                        ),
                    ));
                }
                let copy_length = sequence.len().min(EVENT_SEQUENCE_COPY_BASES);
                copy_sequence =
                    Some(String::from_utf8_lossy(&sequence[..copy_length]).into_owned());
                if sequence.len() > copy_length {
                    fields.push((
                        "Copy limit".to_owned(),
                        format!(
                            "first {copy_length} of {} bases; export is required for the complete event",
                            sequence.len()
                        ),
                    ));
                }
            }
            SequenceData::NotLoaded => {
                fields.push(("Sequence preview".to_owned(), "not loaded".to_owned()));
            }
            SequenceData::Missing => {
                fields.push(("Sequence preview".to_owned(), "missing".to_owned()));
            }
        }
    }
    Some(ReadEventDetails {
        fields,
        copy_sequence,
    })
}

fn bounded_sequence_preview(sequence: &[u8]) -> String {
    let preview_length = sequence.len().min(EVENT_SEQUENCE_PREVIEW_BASES);
    let mut preview = String::from_utf8_lossy(&sequence[..preview_length]).into_owned();
    if sequence.len() > preview_length {
        let remaining = sequence.len() - preview_length;
        let _ = write!(preview, "… (+{remaining} bases)");
    }
    preview
}

fn bounded_sequence_copy(sequence: &[u8]) -> BoundedSequenceCopy {
    let copied_bases = sequence.len().min(SEQUENCE_COPY_BASES);
    BoundedSequenceCopy {
        text: String::from_utf8_lossy(&sequence[..copied_bases]).into_owned(),
        copied_bases,
        total_bases: sequence.len(),
    }
}

fn bounded_oriented_sequence_copy(sequence: &[u8], reverse: bool) -> BoundedSequenceCopy {
    let copied_bases = sequence.len().min(SEQUENCE_COPY_BASES);
    if !reverse {
        return BoundedSequenceCopy {
            text: String::from_utf8_lossy(&sequence[..copied_bases]).into_owned(),
            copied_bases,
            total_bases: sequence.len(),
        };
    }
    let text = (0..copied_bases)
        .filter_map(|position| {
            sequence
                .get(sequence.len().checked_sub(position.saturating_add(1))?)
                .copied()
                .map(complement_base)
                .map(char::from)
        })
        .collect();
    BoundedSequenceCopy {
        text,
        copied_bases,
        total_bases: sequence.len(),
    }
}

fn sequence_copy_hover(sequence: Option<&BoundedSequenceCopy>, kind: &str) -> String {
    sequence.map_or_else(String::new, |sequence| {
        if sequence.copied_bases == sequence.total_bases {
            format!("Copy all {} {kind} bases", sequence.total_bases)
        } else {
            format!(
                "Copy the first {} of {} {kind} bases; use export for the complete sequence",
                sequence.copied_bases, sequence.total_bases
            )
        }
    })
}

fn inspector_fields_text(fields: &[(String, String)]) -> String {
    fields
        .iter()
        .map(|(label, value)| format!("{label}: {value}"))
        .collect::<Vec<_>>()
        .join("\n")
}

const MAX_FEATURE_INSPECTOR_BLOCKS: usize = 128;
const MAX_FEATURE_INSPECTOR_ATTRIBUTES: usize = 256;
const MAX_FEATURE_INSPECTOR_VALUE_BYTES: usize = 4_096;

#[allow(clippy::too_many_lines)]
fn feature_inspector_fields(inspector: &FeatureInspectorSnapshot) -> Vec<(String, String)> {
    let record = &inspector.record;
    let mut fields = vec![
        ("Track".to_owned(), inspector.track_name.clone()),
        (
            "Name".to_owned(),
            record.name.clone().unwrap_or_else(|| "unnamed".to_owned()),
        ),
        (
            "Type".to_owned(),
            record
                .feature_type
                .clone()
                .unwrap_or_else(|| "feature".to_owned()),
        ),
        (
            "Location".to_owned(),
            format!(
                "{}:{}-{} ({} bp; one-based display)",
                record.contig,
                record.start.saturating_add(1),
                record.end,
                record.end.saturating_sub(record.start)
            ),
        ),
        (
            "Strand".to_owned(),
            match record.strand {
                rgv_hts::Strand::Forward => "+",
                rgv_hts::Strand::Reverse => "-",
                rgv_hts::Strand::Unstranded => "unstranded",
            }
            .to_owned(),
        ),
        (
            "Score".to_owned(),
            record
                .score
                .map_or_else(|| "not supplied".to_owned(), |score| score.to_string()),
        ),
    ];
    if let Some((start, end)) = record.coding_interval {
        fields.push((
            "Coding sequence".to_owned(),
            format!("{}-{} (one-based display)", start.saturating_add(1), end),
        ));
    } else if record.feature_type.as_deref() == Some("transcript") {
        fields.push(("Coding sequence".to_owned(), "non-coding / none".to_owned()));
    }
    if !record.blocks.is_empty() {
        let mut exons = record
            .blocks
            .iter()
            .take(MAX_FEATURE_INSPECTOR_BLOCKS)
            .map(|(start, end)| format!("{}-{}", start.saturating_add(1), end))
            .collect::<Vec<_>>()
            .join(", ");
        if record.blocks.len() > MAX_FEATURE_INSPECTOR_BLOCKS {
            let _ = write!(
                exons,
                " … [{} more omitted]",
                record.blocks.len() - MAX_FEATURE_INSPECTOR_BLOCKS
            );
        }
        let block_label = if record.feature_type.as_deref() == Some("PSL alignment") {
            "Alignment blocks"
        } else {
            "Exons"
        };
        fields.push((format!("{block_label} ({})", record.blocks.len()), exons));
    }
    if let Some(peak) = record.peak {
        fields.extend([
            ("Signal value".to_owned(), peak.signal_value.to_string()),
            (
                "p-value (-log10)".to_owned(),
                peak.p_value
                    .map_or_else(|| "not supplied".to_owned(), |value| value.to_string()),
            ),
            (
                "q-value (-log10 FDR)".to_owned(),
                peak.q_value
                    .map_or_else(|| "not supplied".to_owned(), |value| value.to_string()),
            ),
            (
                "Called summit".to_owned(),
                peak.summit.map_or_else(
                    || "not supplied".to_owned(),
                    |summit| {
                        format!(
                            "{}:{} (offset {} bp)",
                            record.contig,
                            summit.saturating_add(1),
                            summit.saturating_sub(record.start)
                        )
                    },
                ),
            ),
        ]);
    }
    for (key, value) in record
        .attributes
        .iter()
        .take(MAX_FEATURE_INSPECTOR_ATTRIBUTES)
    {
        let mut value = value.clone();
        if value.len() > MAX_FEATURE_INSPECTOR_VALUE_BYTES {
            truncate_string_to_bytes(&mut value, MAX_FEATURE_INSPECTOR_VALUE_BYTES - 3);
            value.push('…');
        }
        fields.push((format!("Attribute · {key}"), value));
    }
    if record.attributes.len() > MAX_FEATURE_INSPECTOR_ATTRIBUTES {
        fields.push((
            "Attribute provenance".to_owned(),
            format!(
                "{} additional attributes omitted from this inspector",
                record.attributes.len() - MAX_FEATURE_INSPECTOR_ATTRIBUTES
            ),
        ));
    }
    fields
}

fn interaction_inspector_fields(inspector: &InteractionInspectorSnapshot) -> Vec<(String, String)> {
    let record = &inspector.query.records[inspector.record_index];
    let endpoint = |endpoint: &rgv_hts::InteractionEndpoint| {
        format!(
            "{}:{}-{}{}{}",
            endpoint.contig,
            endpoint.start.saturating_add(1),
            endpoint.end,
            endpoint
                .name
                .as_deref()
                .map_or_else(String::new, |name| format!(" · {name}")),
            match endpoint.strand {
                rgv_hts::Strand::Forward => " · +",
                rgv_hts::Strand::Reverse => " · -",
                rgv_hts::Strand::Unstranded => "",
            },
        )
    };
    let provenance = inspector.query.provenance;
    vec![
        ("Track".to_owned(), inspector.track_name.clone()),
        (
            "Name".to_owned(),
            record.name.clone().unwrap_or_else(|| "unnamed".to_owned()),
        ),
        ("Source".to_owned(), endpoint(&record.source)),
        ("Target".to_owned(), endpoint(&record.target)),
        (
            "Directionality".to_owned(),
            if record.directional {
                "source → target"
            } else {
                "undirected"
            }
            .to_owned(),
        ),
        (
            "Score / value".to_owned(),
            format!(
                "{} / {}",
                record
                    .score
                    .map_or_else(|| "missing".to_owned(), |value| value.to_string()),
                record
                    .value
                    .map_or_else(|| "missing".to_owned(), |value| value.to_string()),
            ),
        ),
        (
            "Experiment".to_owned(),
            record
                .experiment
                .clone()
                .unwrap_or_else(|| "not supplied".to_owned()),
        ),
        (
            "Display provenance".to_owned(),
            format!(
                "{} · minimum score {} · scale {} · labels {}",
                match inspector.settings.display_mode {
                    InteractionDisplayMode::Arcs => "arcs",
                    InteractionDisplayMode::Blocks => "blocks",
                },
                inspector
                    .settings
                    .minimum_score
                    .map_or_else(|| "none".to_owned(), |value| value.to_string()),
                inspector
                    .settings
                    .fixed_maximum_score
                    .map_or_else(|| "automatic".to_owned(), |value| format!("fixed {value}")),
                if inspector.settings.show_labels {
                    "shown"
                } else {
                    "hidden"
                },
            ),
        ),
        (
            "Query provenance".to_owned(),
            format!(
                "{} endpoint entries examined · {} duplicate entries ignored · {} filtered{}",
                provenance.endpoint_entries_examined,
                provenance.duplicate_entries_ignored,
                provenance.records_filtered,
                if provenance.records_truncated {
                    " · record cap reached"
                } else {
                    " · complete"
                },
            ),
        ),
    ]
}

fn endpoint_center_position(start: u64, end: u64) -> u64 {
    start.saturating_add(end.saturating_sub(start) / 2)
}

fn interaction_track_settings_ui(ui: &mut egui::Ui, settings: &mut InteractionTrackSettings) {
    ui.heading("Interaction display");
    ui.horizontal(|ui| {
        egui::ComboBox::from_label("Layout")
            .selected_text(match settings.display_mode {
                InteractionDisplayMode::Arcs => "Arcs",
                InteractionDisplayMode::Blocks => "Blocks and connectors",
            })
            .show_ui(ui, |ui| {
                ui.selectable_value(
                    &mut settings.display_mode,
                    InteractionDisplayMode::Arcs,
                    "Arcs",
                );
                ui.selectable_value(
                    &mut settings.display_mode,
                    InteractionDisplayMode::Blocks,
                    "Blocks and connectors",
                );
            });
    });
    let mut filter_enabled = settings.minimum_score.is_some();
    if ui
        .checkbox(&mut filter_enabled, "Require minimum score")
        .changed()
    {
        settings.minimum_score = filter_enabled.then_some(0.0);
    }
    if let Some(minimum) = &mut settings.minimum_score {
        ui.add(
            egui::DragValue::new(minimum)
                .range(0.0..=f32::MAX)
                .speed(1.0)
                .prefix("Minimum "),
        );
    }
    let mut fixed_scale = settings.fixed_maximum_score.is_some();
    if ui.checkbox(&mut fixed_scale, "Fixed score scale").changed() {
        settings.fixed_maximum_score = fixed_scale.then_some(1_000.0);
    }
    if let Some(maximum) = &mut settings.fixed_maximum_score {
        ui.add(
            egui::DragValue::new(maximum)
                .range(f32::EPSILON..=f32::MAX)
                .speed(1.0)
                .prefix("Maximum "),
        );
    }
    ui.checkbox(&mut settings.show_labels, "Show bounded interaction labels");
    ui.small(
        "Minimum score is applied before the query cap. Cross-chromosome endpoints are shown as labelled vertical markers and can open linked panels.",
    );
}

#[allow(clippy::too_many_lines)]
fn quantitative_inspector_fields(
    inspector: &QuantitativeInspectorSnapshot,
) -> Vec<(String, String)> {
    let record = &inspector.query.records[inspector.record_index];
    let settings = &inspector.settings;
    let scale = match settings.scale_mode {
        QuantitativeScaleMode::Automatic => "per-track automatic".to_owned(),
        QuantitativeScaleMode::Fixed => format!(
            "fixed {} to {}",
            settings.fixed_minimum, settings.fixed_maximum
        ),
        QuantitativeScaleMode::Shared => "shared visible compatible tracks".to_owned(),
    };
    let transform = match settings.scale_transform {
        QuantitativeScaleTransform::Linear => "linear",
        QuantitativeScaleTransform::SignedLog10 => "signed log10(1 + |value|)",
    };
    let window = match settings.window_function {
        QuantitativeWindowFunction::Raw => "raw / no windowing",
        QuantitativeWindowFunction::Minimum => "minimum per screen window",
        QuantitativeWindowFunction::Mean => "base-weighted mean per screen window",
        QuantitativeWindowFunction::Maximum => "maximum per screen window",
    };
    let provenance = inspector.query.provenance;
    let mut fields = vec![
        ("Track".to_owned(), inspector.track_name.clone()),
        (
            "Selected position".to_owned(),
            inspector.selected_position.saturating_add(1).to_string(),
        ),
        (
            "Source interval".to_owned(),
            format!(
                "{}-{} ({} bp)",
                record.start.saturating_add(1),
                record.end,
                record.end.saturating_sub(record.start)
            ),
        ),
        (
            "Source value".to_owned(),
            if record.value.is_finite() {
                format!("{}", record.value)
            } else {
                "non-finite / treated as missing".to_owned()
            },
        ),
        ("Baseline".to_owned(), settings.baseline.to_string()),
        (
            "Displayed scale".to_owned(),
            format!("{scale} · {transform}"),
        ),
        (
            "Window provenance".to_owned(),
            format!(
                "{window}; selected value is the exact source interval, not its rendered aggregate"
            ),
        ),
        (
            "Query provenance".to_owned(),
            format!(
                "{} retained / {} examined · {} non-finite{}",
                provenance.records_retained,
                provenance.records_examined,
                provenance.non_finite_records,
                if provenance.records_truncated {
                    " · source record cap reached"
                } else {
                    " · complete"
                }
            ),
        ),
    ];
    if let Some(rgv_hts::QuantitativeSourceMetadata::Tdf(metadata)) =
        &inspector.query.source_metadata
    {
        fields.push((
            "TDF channel".to_owned(),
            metadata.selected_track_name.clone(),
        ));
        fields.push((
            "TDF channels".to_owned(),
            format!(
                "{} of {}{}",
                metadata.selected_track_index + 1,
                metadata.track_count,
                if metadata.track_count > 1 {
                    " · every embedded channel is opened as an independent track"
                } else {
                    ""
                }
            ),
        ));
        fields.push(("TDF dataset".to_owned(), metadata.dataset.clone()));
        fields.push((
            "TDF resolution".to_owned(),
            metadata.zoom.map_or_else(
                || "raw / unwindowed".to_owned(),
                |zoom| format!("zoom {zoom} · {}", metadata.window_function),
            ),
        ));
        fields.push((
            "TDF format".to_owned(),
            format!(
                "version {} · {}{}",
                metadata.version,
                metadata.data_type,
                if metadata.compressed {
                    " · compressed tiles"
                } else {
                    ""
                }
            ),
        ));
        if let Some(genome_id) = &metadata.genome_id {
            fields.push(("TDF genome".to_owned(), genome_id.clone()));
        }
    }
    if settings.arithmetic != QuantitativeArithmetic::None {
        let operation = match settings.arithmetic {
            QuantitativeArithmetic::None => unreachable!(),
            QuantitativeArithmetic::Add => "add",
            QuantitativeArithmetic::Subtract => "subtract",
            QuantitativeArithmetic::Multiply => "multiply",
            QuantitativeArithmetic::Divide => "divide",
        };
        let operand = inspector.operand.as_ref();
        fields.push((
            "Arithmetic".to_owned(),
            format!(
                "{operation} {}",
                operand.map_or("unavailable operand", |operand| operand.name.as_str())
            ),
        ));
        let derived = operand.and_then(|operand| {
            quantitative_arithmetic_value(record.value, operand.value?, settings.arithmetic)
        });
        fields.push((
            "Operand value".to_owned(),
            operand.and_then(|operand| operand.value).map_or_else(
                || "missing at selected position".to_owned(),
                |value| value.to_string(),
            ),
        ));
        fields.push((
            "Derived value".to_owned(),
            derived.map_or_else(
                || {
                    if settings.arithmetic == QuantitativeArithmetic::Divide
                        && operand.and_then(|operand| operand.value) == Some(0.0)
                    {
                        "missing (division by zero)".to_owned()
                    } else {
                        "missing because both finite operands are required".to_owned()
                    }
                },
                |value| value.to_string(),
            ),
        ));
    }
    fields
}

fn gwas_inspector_fields(inspector: &GwasInspectorSnapshot) -> Vec<(String, String)> {
    let record = &inspector.query.records[inspector.record_index];
    let provenance = inspector.query.provenance;
    let exact_p = record
        .fields
        .iter()
        .find(|(key, _)| {
            matches!(
                key.trim_start_matches('#').to_ascii_lowercase().as_str(),
                "p" | "pval" | "p-value" | "pvalue" | "p.value"
            )
        })
        .map_or_else(|| record.p_value.to_string(), |(_, value)| value.clone());
    let mut fields = vec![
        ("Track".to_owned(), inspector.track_name.clone()),
        ("Association".to_owned(), record.identifier.clone()),
        (
            "Location".to_owned(),
            format!(
                "{}:{} (one-based display)",
                record.contig,
                record.position + 1
            ),
        ),
        ("Exact source p-value".to_owned(), exact_p),
        (
            "-log10(p)".to_owned(),
            if record.minus_log10_p.is_infinite() {
                "+infinity (source p-value is zero; displayed at scale maximum)".to_owned()
            } else {
                record.minus_log10_p.to_string()
            },
        ),
        (
            "Display".to_owned(),
            format!(
                "{} px points · maximum -log10(p) {} · {} colours",
                inspector.settings.point_size,
                inspector.settings.maximum_score,
                match inspector.settings.color_mode {
                    GwasColorMode::Chromosome => "chromosome palette",
                    GwasColorMode::Alternating => "alternating chromosome",
                    GwasColorMode::Uniform => "uniform",
                }
            ),
        ),
        (
            "Query provenance".to_owned(),
            format!(
                "{} retained / {} examined · {} missing-p rows ignored{}",
                provenance.records_retained,
                provenance.records_examined,
                provenance.source_rows_ignored,
                if provenance.records_truncated {
                    " · positional strongest-point cap applied"
                } else {
                    " · complete"
                }
            ),
        ),
    ];
    fields.extend(
        record
            .fields
            .iter()
            .map(|(key, value)| (format!("Source column · {key}"), value.clone())),
    );
    fields
}

