    #[test]
    fn run_marker_detects_unclean_exit_and_clears_on_finish() {
        let directory = tempfile::tempdir().unwrap();
        let settings = directory.path().join("settings.json");
        let first = RunMarker::start(&settings);
        assert!(!first.previous_unclean_exit());
        drop(first);

        let mut recovered = RunMarker::start(&settings);
        assert!(recovered.previous_unclean_exit());
        recovered.finish();
        assert!(!directory.path().join("rgv-running.marker").exists());
    }

    #[test]
    fn autosave_names_are_stable_and_retention_is_scoped_per_project() {
        let directory = tempfile::tempdir().unwrap();
        let settings = directory.path().join("settings.json");
        let first_project = directory.path().join("tumour review.json");
        let second_project = directory.path().join("normal.json");
        let first_prefix = autosave_group_prefix(Some(&first_project));
        let second_prefix = autosave_group_prefix(Some(&second_project));
        assert!(first_prefix.starts_with("tumour_review-"));
        assert_ne!(first_prefix, second_prefix);

        let autosaves = autosave_directory(&settings);
        std::fs::create_dir(&autosaves).unwrap();
        for millisecond in 1..=4 {
            let (path, prefix) = autosave_snapshot_path(
                &settings,
                Some(&first_project),
                UNIX_EPOCH + Duration::from_millis(millisecond),
            );
            assert_eq!(prefix, first_prefix);
            std::fs::write(path, b"snapshot").unwrap();
        }
        let (other, _) = autosave_snapshot_path(
            &settings,
            Some(&second_project),
            UNIX_EPOCH + Duration::from_millis(1),
        );
        std::fs::write(&other, b"other").unwrap();

        prune_autosaves(&autosaves, &first_prefix, 2).unwrap();
        let candidates = discover_recovery_candidates(&settings);
        assert_eq!(candidates.len(), 3);
        assert!(candidates.contains(&other));
        assert_eq!(
            candidates
                .iter()
                .filter(|path| {
                    path.file_name()
                        .unwrap()
                        .to_string_lossy()
                        .starts_with(&first_prefix)
                })
                .count(),
            2
        );
    }

    #[test]
    fn custom_style_tags_follow_sam_tag_syntax() {
        assert_eq!(parse_style_tag("NM"), Some(*b"NM"));
        assert_eq!(parse_style_tag("X1"), Some(*b"X1"));
        assert_eq!(parse_style_tag("1X"), None);
        assert_eq!(parse_style_tag("ABC"), None);
        assert_ne!(
            alignment_color_mode_fingerprint(AlignmentColorMode::Tag(*b"NM")),
            alignment_color_mode_fingerprint(AlignmentColorMode::Tag(*b"HP"))
        );
        let smrt_modes = [
            SmrtKineticsMode::SubreadIpd,
            SmrtKineticsMode::SubreadPulseWidth,
            SmrtKineticsMode::CcsForwardIpd,
            SmrtKineticsMode::CcsForwardPulseWidth,
            SmrtKineticsMode::CcsReverseIpd,
            SmrtKineticsMode::CcsReversePulseWidth,
        ];
        let fingerprints = smrt_modes
            .map(|mode| alignment_color_mode_fingerprint(AlignmentColorMode::SmrtKinetics(mode)));
        assert_eq!(
            fingerprints
                .into_iter()
                .collect::<std::collections::HashSet<_>>()
                .len(),
            6
        );
        let sbx_default = SbxDisplayOptions::default();
        assert_ne!(
            alignment_color_mode_fingerprint(AlignmentColorMode::Sbx(sbx_default)),
            alignment_color_mode_fingerprint(AlignmentColorMode::Sbx(SbxDisplayOptions {
                simplex_tail_mode: SbxSimplexTailMode::Hide,
                ..sbx_default
            }))
        );
        let ultima_default = UltimaDisplayOptions::default();
        assert_ne!(
            alignment_color_mode_fingerprint(AlignmentColorMode::Ultima(ultima_default)),
            alignment_color_mode_fingerprint(AlignmentColorMode::Ultima(UltimaDisplayOptions {
                quality_mode: UltimaQualityMode::Minimum,
                ..ultima_default
            }))
        );
        assert_ne!(
            alignment_color_mode_fingerprint(AlignmentColorMode::Ultima(ultima_default)),
            alignment_color_mode_fingerprint(AlignmentColorMode::Ultima(UltimaDisplayOptions {
                maximum_homopolymer_length_override: Some(12),
                ..ultima_default
            }))
        );
        assert_ne!(
            alignment_color_mode_fingerprint(AlignmentColorMode::Sbx(sbx_default)),
            alignment_color_mode_fingerprint(AlignmentColorMode::Sbx(SbxDisplayOptions {
                discordant_quality_maximum: 11,
                ..sbx_default
            }))
        );
    }

    #[test]
    fn shifted_macos_wheel_uses_horizontal_fallback_for_vertical_scroll() {
        let horizontal_line = wheel_primary_axis(MouseScrollDelta::LineDelta(2.0, 0.0));
        let horizontal_pixel = wheel_primary_axis(MouseScrollDelta::PixelDelta(
            PhysicalPosition::new(-24.0, 0.0),
        ));
        let vertical_wins = wheel_primary_axis(MouseScrollDelta::LineDelta(8.0, -1.0));
        assert!((horizontal_line - 80.0).abs() < f32::EPSILON);
        assert!((horizontal_pixel + 24.0).abs() < f32::EPSILON);
        assert!((vertical_wins + 40.0).abs() < f32::EPSILON);
    }

    #[test]
    fn overview_drag_combines_pointer_anchored_zoom_and_pan() {
        let origin = Viewport::new(
            GenomicInterval::new(ContigId::new(0), 1_000, 2_000).unwrap(),
            1_000.0,
        )
        .unwrap();
        let zoomed = overview_drag_step(origin, 0.25, 0.0, 80.0, 10_000).unwrap();
        assert!(zoomed.interval().len() < origin.interval().len());
        let anchored = zoomed.interval().start() as f64 + zoomed.interval().len() as f64 * 0.25;
        assert!((anchored - 1_250.0).abs() <= 1.0);

        let panned = overview_drag_step(origin, 0.25, 100.0, 0.0, 10_000).unwrap();
        assert!((panned.span() - 1_000.0).abs() < f64::EPSILON);
        assert!(panned.exact_start() > 1_100.0);

        let fine_pan = overview_drag_step(zoomed, 0.25, 100.0, 0.0, 10_000).unwrap();
        let coarse_shift = panned.exact_start() - origin.exact_start();
        let fine_shift = fine_pan.exact_start() - zoomed.exact_start();
        assert!(fine_shift < coarse_shift);
        assert!(overview_pan_gain(10_000.0, 10_000) > overview_pan_gain(100.0, 10_000));
    }

    #[test]
    fn overview_pan_remains_continuous_at_single_base_zoom() {
        let mut viewport = Viewport::new(
            GenomicInterval::new(ContigId::new(0), 1_000, 1_001).unwrap(),
            1_000.0,
        )
        .unwrap();
        for _ in 0..100 {
            let previous = viewport.exact_start();
            viewport = overview_drag_step(viewport, 0.5, 1.0, 0.0, 10_000).unwrap();
            assert!(viewport.exact_start() > previous);
        }
        let expected = 1_000.0 + overview_pan_gain(1.0, 10_000) * 0.1;
        assert!((viewport.exact_start() - expected).abs() < 1.0e-8);
        assert!((viewport.span() - 1.0).abs() < f64::EPSILON);
    }

    #[test]
    fn fine_scale_handle_press_never_becomes_a_chromosome_jump() {
        let viewport = Viewport::new(
            GenomicInterval::new(ContigId::new(0), 906_340, 906_341).unwrap(),
            1_000.0,
        )
        .unwrap();
        // At chromosome scale a pointer pixel inside the minimum-width visual
        // handle can map thousands of bases away from the exact viewport.
        let mapped_pointer_position = 908_000;
        let (handle_viewport, anchor) =
            overview_drag_origin(viewport, mapped_pointer_position, Some(0.5), 3_000_000);
        assert_eq!(handle_viewport, viewport);
        assert!((anchor - 0.5).abs() < f64::EPSILON);

        let (rail_viewport, _) =
            overview_drag_origin(viewport, mapped_pointer_position, None, 3_000_000);
        assert_ne!(rail_viewport.interval(), viewport.interval());
        assert!(rail_viewport.interval().contains(mapped_pointer_position));
    }

    #[test]
    fn zoom_out_retains_data_from_the_overlapping_loaded_interval() {
        let contig = ContigId::new(0);
        let loaded = GenomicInterval::new(contig, 904_160, 904_392).unwrap();
        let expanded_view = GenomicInterval::new(contig, 897_845, 910_760).unwrap();
        assert!(!loaded.contains_interval(expanded_view));
        assert!(retained_data_overlaps(loaded, expanded_view));

        let disjoint_view = GenomicInterval::new(contig, 920_000, 930_000).unwrap();
        assert!(!retained_data_overlaps(loaded, disjoint_view));
    }

